args.text:
/**
 * Coins, tips, the Ink Streak multiplier, night stars and Madame Mantis's critic rating.
 */

import { ON_TIME_SHARE, STREAK_TIERS, TUNING } from './config.js';

/** The Ink Streak multiplier for a run of on-time perfect serves. */
export function streakMultiplier(streak) {
  let mult = 1;
  for (const tier of STREAK_TIERS) if (streak >= tier.at) mult = tier.mult;
  return mult;
}

/** The streak needed for the next multiplier tier, or null at the top tier. */
export function nextStreakTier(streak) {
  const next = STREAK_TIERS.find((tier) => tier.at > streak);
  return next ? next.at : null;
}

/**
 * Prices one serve. Cooked parts (anything a station heats) can be perfect or merely ok;
 * a cold plate from the pass loses its perfect tips.
 */
export function scoreServe({ recipe, customer, parts, patienceFrac, cold, streak }) {
  const cooked = parts.filter((p) => p.prep !== 'raw' && p.prep !== 'chop');
  const perfectCooked = cooked.filter((p) => p.quality === 'perfect').length;
  const allPerfect = cooked.every((p) => p.quality === 'perfect');
  const base = recipe.price;
  const speedTip = Math.round(base * TUNING.speedTipShare * patienceFrac);
  let perfectTip = 0;
  if (!cold) {
    perfectTip = perfectCooked * TUNING.perfectPartTip * customer.perfectTipMul;
    if (allPerfect && cooked.length > 0) perfectTip += TUNING.allPerfectTip * customer.perfectTipMul;
  }
  const onTime = patienceFrac >= ON_TIME_SHARE;
  const perfect = allPerfect && !cold;
  const nextStreak = onTime && perfect ? streak + 1 : 0;
  const mult = streakMultiplier(streak);
  const total = Math.round((base + speedTip + perfectTip) * mult);
  return { base, speedTip, perfectTip, mult, total, perfect, onTime, nextStreak, perfectCooked };
}

/** Stars for a night: coin targets, and on critic nights three stars also need a 4-star review. */
export function starsFor(coins, targets, criticScore = null) {
  let stars = targets.filter((t) => coins >= t).length;
  if (criticScore !== null && stars === 3 && criticScore < 4) stars = 2;
  return stars;
}

/** Madame Mantis's live rating while she waits: she starts delighted and cools as patience drains. */
export function criticLiveStars(patienceFrac) {
  return Math.round((2 + 3 * patienceFrac) * 2) / 2;
}

/** Madame Mantis's final verdict for a served plate, from 1 to 5 in half stars. */
export function criticVerdict(parts, patienceFrac, cold) {
  const cooked = parts.filter((p) => p.prep !== 'raw' && p.prep !== 'chop');
  const perfectShare = cooked.length ? cooked.filter((p) => p.quality === 'perfect').length / cooked.length : 1;
  const raw = 1 + 2.5 * (cold ? perfectShare * 0.5 : perfectShare) + 1.5 * patienceFrac;
  return Math.max(1, Math.min(5, Math.round(raw * 2) / 2));
}

/**
 * Tickets on the Current Board, the customers behind them, the Clam Plate where dishes are
 * assembled, and the Current Window where finished plates wait to be served.
 */

import { LAYOUT, TUNING } from './config.js';
import { CUSTOMERS } from './data/customers.js';
import { RECIPE } from './data/recipes.js';
import { ARM_HOLD, holdingArms, releaseArm, sendArm } from './arms.js';
import { criticLiveStars, criticVerdict, scoreServe } from './scoring.js';

const PLATE_POINT = { x: LAYOUT.plate.x, y: LAYOUT.plate.y - 12 };

/** Adds a ticket for a customer; twins share a pair id. */
export function spawnTicket(state, customerId, recipeId, pairId = null) {
  const customer = CUSTOMERS[customerId];
  const calm = state.upgrades.calmingCoral ? 1 / TUNING.calmingDrain : 1;
  const ticket = {
    id: state.nextTicketId++, customerId, recipeId, pairId,
    patience: customer.patience, maxPatience: customer.patience, drain: 1 / calm,
    born: state.time, changed: false, critic: !!customer.vip,
  };
  state.tickets.push(ticket);
  if (state.selectedTicket === null) state.selectedTicket = ticket.id;
  state.events.push({ type: 'spawn', ticket: ticket.id, customer: customerId });
  return ticket;
}

/** Spawns the next regular from the night's weighted pool; the twins arrive as two tickets. */
export function spawnRegular(state) {
  const cfg = state.cfg;
  const menu = cfg.recipes;
  let customerId = state.rng.weighted(cfg.customers);
  if (customerId === 'twins' && state.tickets.length + 2 > state.maxTickets) customerId = 'puffy';
  if (customerId === 'twins') {
    const pair = state.nextTicketId;
    spawnTicket(state, 'twins', state.rng.pick(menu), pair);
    spawnTicket(state, 'twins', state.rng.pick(menu), pair);
    return;
  }
  spawnTicket(state, customerId, state.rng.pick(menu));
}

/** Madame Mantis arrives with her standing order, the Grand Reef Platter. */
export function spawnCritic(state) {
  spawnTicket(state, 'mantis', 'platter');
  state.events.push({ type: 'criticArrives' });
}

/** Share of patience left on a ticket, 0..1. */
export function patienceShare(ticket) {
  return Math.max(0, ticket.patience / ticket.maxPatience);
}

/** Drains patience, lets Shelby change her mind once, and walks out customers who waited too long. */
export function updateTickets(state, dt) {
  for (const ticket of [...state.tickets]) {
    ticket.patience -= dt * ticket.drain;
    if (ticket.customerId === 'shelby' && !ticket.changed && patienceShare(ticket) <= TUNING.shelbyChangeAt) {
      const options = state.cfg.recipes.filter((r) => r !== ticket.recipeId);
      ticket.recipeId = state.rng.pick(options);
      ticket.changed = true;
      ticket.patience = Math.min(ticket.maxPatience, ticket.patience + TUNING.shelbyPatienceGift);
      state.stats.ordersChanged++;
      state.events.push({ type: 'orderChanged', ticket: ticket.id });
      state.toast('Shelby swapped shells and changed her order!', '#ffd166');
    }
    if (ticket.patience <= 0) missTicket(state, ticket);
  }
  const critic = state.tickets.find((t) => t.critic);
  state.critic.live = critic ? criticLiveStars(patienceShare(critic)) : null;
}

/** A customer leaves unserved: the Ink Streak breaks. */
function missTicket(state, ticket) {
  removeTicket(state, ticket.id);
  state.stats.missed++;
  if (state.streak > 0) state.events.push({ type: 'streakBroken' });
  state.streak = 0;
  if (ticket.critic) state.critic.reviews.push(1);
  state.events.push({ type: 'miss', ticket: ticket.id, customer: ticket.customerId });
  state.toast(`${CUSTOMERS[ticket.customerId].name} swam off hungry`, '#ef5b4c');
}

function removeTicket(state, id) {
  state.tickets = state.tickets.filter((t) => t.id !== id);
  if (state.selectedTicket === id) state.selectedTicket = state.tickets[0]?.id ?? null;
}

/** Selects a ticket by id, or the next one on the board for 'next'. */
export function selectTicket(state, id) {
  if (!state.tickets.length) return { ok: false, reason: 'No tickets yet' };
  if (id === 'next') {
    const i = state.tickets.findIndex((t) => t.id === state.selectedTicket);
    state.selectedTicket = state.tickets[(i + 1) % state.tickets.length].id;
  } else if (state.tickets.some((t) => t.id === id)) {
    state.selectedTicket = id;
  } else {
    return { ok: false, reason: 'That customer has left' };
  }
  state.events.push({ type: 'select' });
  return { ok: true };
}

/** The parts of the plate's recipe that are still missing. */
export function missingParts(recipeId, plateParts) {
  const left = [...plateParts];
  return RECIPE[recipeId].parts.filter(([ing, prep]) => {
    const i = left.findIndex((p) => p.ing === ing && p.prep === prep);
    if (i < 0) return true;
    left.splice(i, 1);
    return false;
  });
}

/** Whether a held item fills a missing part of a recipe. */
function fits(recipeId, plateParts, item) {
  return missingParts(recipeId, plateParts).some(([ing, prep]) => ing === item.ing && prep === item.prep);
}

/** The recipe the plate should build when it is empty: the selected ticket's, else any ticket a held item fits. */
function chooseRecipe(state, held) {
  const order = [...state.tickets].sort((a, b) => (a.id === state.selectedTicket ? -1 : b.id === state.selectedTicket ? 1 : 0));
  for (const ticket of order) {
    if (held.some((arm) => fits(ticket.recipeId, [], arm.item))) return ticket;
  }
  return null;
}

/**
 * The Clam Plate (Space or a click): finish a complete dish onto the pass, or lay every held
 * item the dish needs onto the plate.
 */
export function usePlate(state) {
  const plate = state.plate;
  if (plate.recipeId && missingParts(plate.recipeId, plate.parts).length === 0) return finishPlate(state);
  const held = holdingArms(state).filter((a) => a.reach <= 0.05);
  if (!plate.recipeId) {
    const ticket = chooseRecipe(state, held);
    if (!ticket) return { ok: false, reason: held.length ? 'No ticket needs that' : 'Hold something first' };
    plate.recipeId = ticket.recipeId;
    state.selectedTicket = ticket.id;
  }
  let placed = 0;
  for (const arm of held) {
    if (!fits(plate.recipeId, plate.parts, arm.item)) continue;
    plate.parts.push(arm.item);
    state.events.push({ type: 'plateAdd', ...PLATE_POINT, ing: arm.item.ing });
    releaseArm(state, arm);
    sendArm(state, arm, PLATE_POINT);
    placed++;
  }
  if (!placed) return { ok: false, reason: 'Nothing held fits this dish' };
  return { ok: true };
}

/** Finishing step: the plate moves to the Current Window if there is room. */
export function finishPlate(state) {
  const plate = state.plate;
  const slots = state.upgrades.biggerPlate ? TUNING.biggerPassSlots : TUNING.passSlots;
  if (state.pass.length >= slots) return { ok: false, reason: 'The Current Window is full: serve first' };
  const recipe = RECIPE[plate.recipeId];
  const warmth = state.upgrades.biggerPlate ? TUNING.biggerPlateWarmth : TUNING.plateWarmth;
  state.pass.push({ id: state.nextPlateId++, recipeId: plate.recipeId, parts: plate.parts, warmth, maxWarmth: warmth });
  state.events.push({ type: 'finish', ...PLATE_POINT, recipe: recipe.id, word: recipe.finish });
  plate.recipeId = null;
  plate.parts = [];
  return { ok: true, info: `${recipe.finish}!` };
}

/** Plates on the pass cool down; a cold plate loses its perfect tips. */
export function updatePass(state, dt) {
  for (const p of state.pass) p.warmth = Math.max(0, p.warmth - dt);
}

/** The ticket a pass plate would go to: the selected one if it matches, else the most impatient match. */
export function ticketForPlate(state, passPlate) {
  const matches = state.tickets.filter((t) => t.recipeId === passPlate.recipeId);
  if (!matches.length) return null;
  return matches.find((t) => t.id === state.selectedTicket) ?? matches.sort((a, b) => a.patience - b.patience)[0];
}

/** Serves a plate from the pass (S or a click on it) to its matching ticket. */
export function servePass(state, index = null) {
  if (!state.pass.length) return { ok: false, reason: 'No plate is ready' };
  const order = index === null ? state.pass.map((_, i) => i) : [index];
  const i = order.find((k) => state.pass[k] && ticketForPlate(state, state.pass[k]));
  if (i === undefined) return { ok: false, reason: 'Nobody ordered that dish' };
  const plate = state.pass[i];
  const ticket = ticketForPlate(state, plate);
  const customer = CUSTOMERS[ticket.customerId];
  const share = patienceShare(ticket);
  const cold = plate.warmth <= 0;
  const result = scoreServe({ recipe: RECIPE[plate.recipeId], customer, parts: plate.parts, patienceFrac: share, cold, streak: state.streak });
  state.pass.splice(i, 1);
  removeTicket(state, ticket.id);
  state.coins += result.total;
  state.stats.served++;
  state.stats.tips += result.speedTip + result.perfectTip;
  state.streak = result.nextStreak;
  state.bestStreak = Math.max(state.bestStreak, state.streak);
  if (ticket.critic) {
    const stars = criticVerdict(plate.parts, share, cold);
    state.critic.reviews.push(stars);
    state.events.push({ type: 'criticVerdict', stars });
  }
  if (ticket.pairId !== null) twinBonus(state, ticket.pairId);
  const slot = slotPoint(i);
  state.events.push({ type: 'serve', ...slot, coins: result.total, perfect: result.perfect, mult: result.mult, ticket: ticket.id, customer: ticket.customerId, streak: state.streak });
  if (cold) state.toast('Cold plate: no perfect tip', '#9fc7d6');
  return { ok: true, result };
}

/** The Seahorse Twins tip extra when both of their plates arrive close together. */
function twinBonus(state, pairId) {
  const first = state.twinsServed[pairId];
  if (first === undefined) {
    state.twinsServed[pairId] = state.time;
    return;
  }
  if (state.time - first <= TUNING.twinsWindow) {
    state.coins += TUNING.twinsBonus;
    state.stats.twins++;
    state.events.push({ type: 'twinBonus', ...slotPoint(0), coins: TUNING.twinsBonus });
    state.toast(`Twin bonus +${TUNING.twinsBonus}`, '#7fd1b9');
  }
  delete state.twinsServed[pairId];
}

/** Centre of a plate slot in the Current Window. */
export function slotPoint(i) {
  const p = LAYOUT.pass;
  return { x: p.x + p.w / 2, y: p.y + 196 + i * 120 };
}

/**
 * Backspace: drop the newest held item, else bin burnt food, else clear the plate, else bin a
 * plate nobody ordered. Everything goes into the ink jar with a puff.
 */
export function trash(state, clearBurnt) {
  const held = holdingArms(state)[0];
  const jar = { x: LAYOUT.trash.x + LAYOUT.trash.w / 2, y: LAYOUT.trash.y + 20 };
  if (held) {
    state.events.push({ type: 'trash', ...ARM_HOLD[held.id], ing: held.item.ing });
    releaseArm(state, held);
    sendArm(state, held, jar);
    return { ok: true, info: 'Binned' };
  }
  for (const [id, st] of Object.entries(state.stations)) {
    const i = st.slots.findIndex((s) => s?.phase === 'burnt');
    if (i >= 0 && clearBurnt(state, id, i)) return { ok: true, info: 'Burnt food binned' };
  }
  if (state.plate.parts.length) {
    state.events.push({ type: 'trash', ...PLATE_POINT });
    state.plate.parts = [];
    state.plate.recipeId = null;
    return { ok: true, info: 'Plate cleared' };
  }
  const stray = state.pass.findIndex((p) => !ticketForPlate(state, p));
  if (stray >= 0) {
    state.events.push({ type: 'trash', ...slotPoint(stray) });
    state.pass.splice(stray, 1);
    return { ok: true, info: 'Unwanted plate binned' };
  }
  return { ok: false, reason: 'Nothing to bin' };
}

/**
 * One tide night of service: the seeded, deterministic rules that tie the arms, stations,
 * tickets, plate and pass together. Input, the scripted chef and the screenshot scenes all
 * drive a night through `dispatch`, and time only moves through `stepNight`.
 */

import { LAYOUT, TUNING } from './config.js';
import { INGREDIENT, INGREDIENTS } from './data/ingredients.js';
import { NIGHTS } from './data/nights.js';
import { createRng } from './rng.js';
import { createArms, freeArmNear, holdItem, sendArm, updateArms } from './arms.js';
import { clearBurnt, createStations, updateStations, useStation } from './stations.js';
import { selectTicket, servePass, spawnCritic, spawnRegular, trash, updatePass, updateTickets, usePlate } from './orders.js';
import { starsFor } from './scoring.js';

/** Centre of an ingredient bin on the counter. */
export function binPoint(index) {
  const b = LAYOUT.bins;
  return { x: b.x + index * (b.w + b.gap) + b.w / 2, y: b.y + 40 };
}

/** A fresh night: empty stations, eight idle arms and the night's ticket schedule. */
export function createNight({ nightIndex, upgrades = {}, seed = 1 }) {
  const cfg = NIGHTS[nightIndex];
  const state = {
    nightIndex, cfg, seed, rng: createRng(seed * 7919 + nightIndex * 104729),
    upgrades: { ...upgrades }, time: 0, over: false,
    coins: 0, streak: 0, bestStreak: 0,
    stats: { served: 0, missed: 0, perfectCooks: 0, burnt: 0, tips: 0, twins: 0, ordersChanged: 0 },
    tickets: [], nextTicketId: 1, nextPlateId: 1, selectedTicket: null, spawnTimer: cfg.firstSpawn,
    maxTickets: cfg.maxTickets, rush: { index: 0, warnAt: null, endsAt: null, active: false },
    criticIndex: 0, critic: { live: null, reviews: [] },
    arms: createArms(), stations: createStations(upgrades),
    plate: { recipeId: null, parts: [] }, pass: [], twinsServed: {},
    events: [], toasts: [],
  };
  state.toast = (text, color = '#fff6e6') => {
    state.toasts.push({ text, color, at: state.time });
    if (state.toasts.length > 3) state.toasts.shift();
  };
  return state;
}

/** Whether a Spring Tide rush is running. */
export function inRush(state) {
  return state.rush.active;
}

/** Advances the night by dt seconds. */
export function stepNight(state, dt) {
  if (state.over) return;
  state.time += dt;
  updateArms(state, dt);
  updateStations(state, dt);
  updateTickets(state, dt);
  updatePass(state, dt);
  updateRush(state);
  updateSpawns(state, dt);
  state.toasts = state.toasts.filter((t) => state.time - t.at < 2.6);
  if (state.time >= state.cfg.duration) endNight(state);
}

/** Spring Tide: a warning banner, then tickets arrive much faster for a while. */
function updateRush(state) {
  const r = state.rush;
  const next = state.cfg.rushes[r.index];
  if (!r.active && next !== undefined) {
    if (r.warnAt === null && state.time >= next - TUNING.rushWarning) {
      r.warnAt = state.time;
      state.events.push({ type: 'rushWarn' });
    }
    if (state.time >= next) {
      r.active = true;
      r.endsAt = next + TUNING.rushDuration;
      state.maxTickets = state.cfg.maxTickets + 2;
      state.spawnTimer = Math.min(state.spawnTimer, 0.8);
      state.events.push({ type: 'rushStart' });
    }
  } else if (r.active && state.time >= r.endsAt) {
    r.active = false;
    r.warnAt = null;
    r.index++;
    state.maxTickets = state.cfg.maxTickets;
    state.events.push({ type: 'rushEnd' });
  }
}

/** Regular tickets on the night's pace, plus Madame Mantis at her booked times. */
function updateSpawns(state, dt) {
  const visit = state.cfg.critic[state.criticIndex];
  if (visit !== undefined && state.time >= visit) {
    spawnCritic(state);
    state.criticIndex++;
  }
  if (state.time > state.cfg.duration - 12) return;
  state.spawnTimer -= dt;
  if (state.spawnTimer > 0) return;
  const pace = state.cfg.spawnEvery * (state.rush.active ? TUNING.rushSpawnFactor : 1);
  if (state.tickets.length < state.maxTickets) {
    spawnRegular(state);
    state.spawnTimer = pace * state.rng.range(0.8, 1.2);
  } else {
    state.spawnTimer = 1;
  }
}

/** An idle arm reaches into a bin and takes one ingredient. */
export function grabIngredient(state, ingId) {
  const index = INGREDIENTS.findIndex((i) => i.id === ingId);
  if (index < 0) return { ok: false, reason: 'Unknown ingredient' };
  const at = binPoint(index);
  const arm = freeArmNear(state, at);
  if (!arm) return { ok: false, reason: 'All eight arms are busy!', noArm: true };
  const ing = INGREDIENT[ingId];
  holdItem(state, arm, { ing: ingId, prep: ing.preps.includes('raw') ? 'raw' : null, quality: 'good' });
  sendArm(state, arm, at);
  state.events.push({ type: 'grab', ...at, ing: ingId });
  return { ok: true };
}

/** Applies one player action; failures leave a toast and an event the audio answers. */
export function dispatch(state, action) {
  if (state.over) return { ok: false, reason: 'The night is over' };
  let res;
  switch (action.type) {
    case 'grab': res = grabIngredient(state, action.ing); break;
    case 'station': res = useStation(state, action.id, action.slot ?? null); break;
    case 'plate': res = usePlate(state); break;
    case 'serve': res = servePass(state, action.index ?? null); break;
    case 'select': res = selectTicket(state, action.id); break;
    case 'cycle': res = selectTicket(state, 'next'); break;
    case 'trash': res = trash(state, clearBurnt); break;
    default: res = { ok: false, reason: 'Unknown action' };
  }
  if (!res.ok) {
    state.events.push({ type: res.noArm ? 'noArm' : 'invalid' });
    state.toast(res.reason, res.noArm ? '#ff7a59' : '#fff6e6');
  }
  return res;
}

/** Closes the bistro for the night. */
function endNight(state) {
  state.over = true;
  state.events.push({ type: 'nightOver' });
}

/** The night's results: coins, stars, stats and the critic's average. */
export function nightSummary(state) {
  const reviews = state.critic.reviews;
  const critic = state.cfg.critic.length ? (reviews.length ? reviews.reduce((a, b) => a + b, 0) / reviews.length : 1) : null;
  return {
    nightIndex: state.nightIndex, coins: state.coins, stars: starsFor(state.coins, state.cfg.stars, critic),
    bestStreak: state.bestStreak, critic, ...state.stats,
  };
}

/**
 * A scripted chef that plays a night through the same `dispatch` actions as the keyboard.
 * The screenshot scenes use it to reach real mid-service states, and it doubles as a
 * play-through check that a night can be finished.
 */

import { RECIPE } from './data/recipes.js';
import { INGREDIENT } from './data/ingredients.js';
import { STATION_KINDS, isUsable } from './stations.js';
import { missingParts, ticketForPlate } from './orders.js';
import { freeArmCount, holdingArms } from './arms.js';
import { dispatch } from './state.js';

const PREP_STATIONS = { chop: ['board'], simmer: ['pot0', 'pot1'], sear: ['grill'], steam: ['steamer'] };

/** Creates a chef that acts at most once per `cadence` seconds. */
export function createAutoChef({ cadence = 0.24, focus = 3 } = {}) {
  return { cadence, focus, cooldown: 0, intents: new Map() };
}

/** Tickets the chef works on: the plate's ticket first, then the least patient. */
function focusTickets(state, chef) {
  const order = [...state.tickets].sort((a, b) => a.patience - b.patience);
  const plateTicket = state.plate.recipeId ? order.find((t) => t.recipeId === state.plate.recipeId) : null;
  const list = plateTicket ? [plateTicket, ...order.filter((t) => t !== plateTicket)] : order;
  return list.slice(0, chef.focus);
}

/** Everything already on its way to a dish: plate parts, held food, food cooking at stations. */
function pipeline(state, chef) {
  const pool = [];
  for (const arm of holdingArms(state)) pool.push({ ing: arm.item.ing, prep: arm.item.prep ?? chef.intents.get(arm.id) ?? null });
  for (const st of Object.values(state.stations)) {
    for (const item of st.slots) if (item && item.phase !== 'burnt') pool.push({ ing: item.ing, prep: item.prep });
  }
  for (const p of state.pass) for (const part of p.parts) pool.push({ ...part, onPass: true });
  return pool;
}

/** Parts still to start, in priority order, after counting the pipeline against focus tickets. */
function missingWork(state, chef) {
  const pool = pipeline(state, chef);
  const passRecipes = state.pass.map((p) => p.recipeId);
  const out = [];
  for (const ticket of focusTickets(state, chef)) {
    const passIndex = passRecipes.indexOf(ticket.recipeId);
    if (passIndex >= 0) {
      passRecipes.splice(passIndex, 1);
      continue;
    }
    const onPlate = state.plate.recipeId === ticket.recipeId ? state.plate.parts : [];
    for (const [ing, prep] of missingParts(ticket.recipeId, onPlate)) {
      const i = pool.findIndex((p) => !p.onPass && p.ing === ing && p.prep === prep);
      if (i >= 0) pool.splice(i, 1);
      else out.push({ ticket, ing, prep });
    }
    if (state.plate.recipeId === ticket.recipeId) state.plate.recipeId = state.plate.recipeId;
  }
  return out;
}

/** A free slot for a preparation, as [stationId, slot], or null. */
function freeSlotFor(state, prep) {
  for (const id of PREP_STATIONS[prep]) {
    const st = state.stations[id];
    if (st.locked) continue;
    const slot = st.slots.findIndex((s) => s === null);
    if (slot >= 0) return [id, slot];
  }
  return null;
}

/** Picks and performs the chef's next action, if its cooldown allows. */
export function chefThink(state, chef, dt) {
  chef.cooldown -= dt;
  if (chef.cooldown > 0 || state.over) return null;
  const action = chooseAction(state, chef);
  if (!action) return null;
  chef.cooldown = chef.cadence;
  const res = dispatch(state, action);
  if (res.ok && action.type === 'grab' && action.prep) {
    const arm = holdingArms(state)[0];
    if (arm) chef.intents.set(arm.id, action.prep);
  }
  return action;
}

/** The decision list: urgent cooking first, then serving, plating and starting new parts. */
function chooseAction(state, chef) {
  const grill = state.stations.grill;
  const flip = grill.slots.findIndex((s) => s?.phase === 'flip');
  if (flip >= 0 && freeArmCount(state) > 0) return { type: 'station', id: 'grill', slot: flip };
  for (const [id, st] of Object.entries(state.stations)) {
    const burnt = st.slots.findIndex((s) => s?.phase === 'burnt');
    if (burnt >= 0) return { type: 'station', id, slot: burnt };
  }
  const servable = state.pass.findIndex((p) => ticketForPlate(state, p));
  if (servable >= 0) return { type: 'serve', index: servable };
  if (state.plate.recipeId && missingParts(state.plate.recipeId, state.plate.parts).length === 0) return { type: 'plate' };

  const needed = missingWork(state, chef).concat(neededFromStations(state, chef));
  for (const [id, st] of Object.entries(state.stations)) {
    for (let i = 0; i < st.slots.length; i++) {
      const item = st.slots[i];
      if (isUsable(item) && (item.phase === 'over' || freeArmCount(state) > 0 || id.startsWith('pot'))) {
        if (isWanted(state, item)) return { type: 'station', id, slot: i };
      }
    }
  }
  const held = holdingArms(state).filter((a) => a.reach <= 0.05);
  for (const arm of held) {
    if (arm.item.prep === null) {
      const prep = chef.intents.get(arm.id) ?? INGREDIENT[arm.item.ing].preps[0];
      const slot = freeSlotFor(state, prep);
      if (slot) return { type: 'station', id: slot[0], slot: slot[1] };
    }
  }
  const plateTicket = state.plate.recipeId ? null : focusTickets(state, chef)[0];
  if (plateTicket && plateTicket.id !== state.selectedTicket && held.some((a) => a.item.prep !== null)) {
    return { type: 'select', id: plateTicket.id };
  }
  if (held.some((a) => a.item.prep !== null && fitsPlate(state, a.item))) return { type: 'plate' };

  if (freeArmCount(state) <= 1 || held.length >= 4) return null;
  for (const part of needed) {
    if (part.prep === 'raw') {
      if (state.plate.recipeId && state.plate.recipeId !== part.ticket.recipeId) continue;
      return { type: 'grab', ing: part.ing, prep: null };
    }
    const waiting = held.filter((a) => a.item.prep === null && (chef.intents.get(a.id) ?? null) === part.prep).length;
    const slot = freeSlotFor(state, part.prep);
    if (slot && waiting === 0) return { type: 'grab', ing: part.ing, prep: part.prep };
  }
  return null;
}

/** Placeholder hook kept for symmetry with missingWork: stations never add extra demand. */
function neededFromStations() {
  return [];
}

/** Whether a station item is wanted by the plate or any ticket. */
function isWanted(state, item) {
  return state.tickets.some((t) => RECIPE[t.recipeId].parts.some(([ing, prep]) => ing === item.ing && prep === item.prep));
}

/** Whether a held, prepared item fits the plate as it stands. */
function fitsPlate(state, item) {
  if (state.plate.recipeId) return missingParts(state.plate.recipeId, state.plate.parts).some(([i, p]) => i === item.ing && p === item.prep);
  return state.tickets.some((t) => RECIPE[t.recipeId].parts.some(([i, p]) => i === item.ing && p === item.prep));
}

/** Runs a whole night with the chef at a fixed step; returns the final state. */
export function simulateNight(state, chef, step = 1 / 60, until = Infinity) {
  while (!state.over && state.time < until) {
    chefThink(state, chef, step);
    state.events.length = 0;
    stepAndKeep(state, step);
  }
  return state;
}

let stepFn = null;
/** Lets the caller provide the step function without a circular import. */
export function useStepper(fn) {
  stepFn = fn;
}
function stepAndKeep(state, step) {
  stepFn(state, step);
}

/** Readable name of a station for logs. */
export function stationName(id) {
  return STATION_KINDS[id]?.name ?? id;
}

/**
 * A scripted chef that plays a night through the same `dispatch` actions as the keyboard.
 * The screenshot scenes use it to reach real mid-service states, and it doubles as a
 * play-through check that every night can be finished.
 */

import { RECIPE } from './data/recipes.js';
import { INGREDIENT } from './data/ingredients.js';
import { isUsable } from './stations.js';
import { missingParts, ticketForPlate } from './orders.js';
import { freeArmCount, holdingArms } from './arms.js';
import { dispatch, stepNight } from './state.js';

const PREP_STATIONS = { chop: ['board'], simmer: ['pot0', 'pot1'], sear: ['grill'], steam: ['steamer'] };

/** Creates a chef that acts at most once per `cadence` seconds and plans `focus` tickets ahead. */
export function createAutoChef({ cadence = 0.24, focus = 3 } = {}) {
  return { cadence, focus, cooldown: 0, intents: new Map() };
}

/** Tickets the chef works on: the plate's ticket first, then the least patient. */
function focusTickets(state, chef) {
  const order = [...state.tickets].sort((a, b) => a.patience - b.patience);
  const plateTicket = state.plate.recipeId ? order.find((t) => t.recipeId === state.plate.recipeId) : null;
  const list = plateTicket ? [plateTicket, ...order.filter((t) => t !== plateTicket)] : order;
  return list.slice(0, chef.focus);
}

/** Everything already on its way to a dish: held food and food cooking at stations. */
function pipeline(state, chef) {
  const pool = [];
  for (const arm of holdingArms(state)) pool.push({ ing: arm.item.ing, prep: arm.item.prep ?? chef.intents.get(arm.id) ?? null });
  for (const st of Object.values(state.stations)) {
    for (const item of st.slots) if (item && item.phase !== 'burnt') pool.push({ ing: item.ing, prep: item.prep });
  }
  return pool;
}

/** Parts still to start, in priority order, once plate, pass and pipeline are counted. */
function missingWork(state, chef) {
  const pool = pipeline(state, chef);
  const passRecipes = state.pass.map((p) => p.recipeId);
  const out = [];
  for (const ticket of focusTickets(state, chef)) {
    const onPass = passRecipes.indexOf(ticket.recipeId);
    if (onPass >= 0) {
      passRecipes.splice(onPass, 1);
      continue;
    }
    const onPlate = state.plate.recipeId === ticket.recipeId ? state.plate.parts : [];
    for (const [ing, prep] of missingParts(ticket.recipeId, onPlate)) {
      const i = pool.findIndex((p) => p.ing === ing && p.prep === prep);
      if (i >= 0) pool.splice(i, 1);
      else out.push({ ticket, ing, prep });
    }
  }
  return out;
}

/** A free slot for a preparation, as [stationId, slot], or null. */
function freeSlotFor(state, prep) {
  for (const id of PREP_STATIONS[prep]) {
    const st = state.stations[id];
    if (st.locked) continue;
    const slot = st.slots.findIndex((s) => s === null);
    if (slot >= 0) return [id, slot];
  }
  return null;
}

/** Whether any ticket on the board wants this ingredient prepared this way. */
function isWanted(state, ing, prep) {
  return state.tickets.some((t) => RECIPE[t.recipeId].parts.some(([i, p]) => i === ing && p === prep));
}

/** Whether a held, prepared item can go on the plate as it stands. */
function fitsPlate(state, item) {
  if (!state.plate.recipeId) return isWanted(state, item.ing, item.prep);
  return missingParts(state.plate.recipeId, state.plate.parts).some(([i, p]) => i === item.ing && p === item.prep);
}

/** The decision list: urgent cooking first, then serving, plating and starting new parts. */
function chooseAction(state, chef) {
  const flip = state.stations.grill.slots.findIndex((s) => s?.phase === 'flip');
  if (flip >= 0 && freeArmCount(state) > 0) return { type: 'station', id: 'grill', slot: flip };
  for (const [id, st] of Object.entries(state.stations)) {
    const burnt = st.slots.findIndex((s) => s?.phase === 'burnt');
    if (burnt >= 0) return { type: 'station', id, slot: burnt };
  }
  const servable = state.pass.findIndex((p) => ticketForPlate(state, p));
  if (servable >= 0) return { type: 'serve', index: servable };
  if (state.plate.recipeId && missingParts(state.plate.recipeId, state.plate.parts).length === 0) return { type: 'plate' };

  for (const [id, st] of Object.entries(state.stations)) {
    for (let i = 0; i < st.slots.length; i++) {
      const item = st.slots[i];
      if (isUsable(item) && isWanted(state, item.ing, item.prep) && (freeArmCount(state) > 0 || id.startsWith('pot'))) {
        return { type: 'station', id, slot: i };
      }
    }
  }
  const held = holdingArms(state).filter((a) => a.reach <= 0.05);
  for (const arm of held) {
    if (arm.item.prep !== null) continue;
    const slot = freeSlotFor(state, chef.intents.get(arm.id) ?? INGREDIENT[arm.item.ing].preps[0]);
    if (slot) return { type: 'station', id: slot[0], slot: slot[1] };
  }
  const lead = focusTickets(state, chef)[0];
  if (!state.plate.recipeId && lead && lead.id !== state.selectedTicket && held.some((a) => a.item.prep !== null)) {
    return { type: 'select', id: lead.id };
  }
  if (held.some((a) => a.item.prep !== null && fitsPlate(state, a.item))) return { type: 'plate' };

  if (freeArmCount(state) <= 1 || held.length >= 4) return null;
  for (const part of missingWork(state, chef)) {
    if (part.prep === 'raw') {
      if (state.plate.recipeId && state.plate.recipeId !== part.ticket.recipeId) continue;
      return { type: 'grab', ing: part.ing, prep: null };
    }
    const waiting = held.some((a) => a.item.prep === null && chef.intents.get(a.id) === part.prep);
    if (!waiting && freeSlotFor(state, part.prep)) return { type: 'grab', ing: part.ing, prep: part.prep };
  }
  return null;
}

/** Picks and performs the chef's next action, if its cooldown allows. */
export function chefThink(state, chef, dt) {
  chef.cooldown -= dt;
  if (chef.cooldown > 0 || state.over) return null;
  const action = chooseAction(state, chef);
  if (!action) return null;
  chef.cooldown = chef.cadence;
  const res = dispatch(state, action);
  if (res.ok && action.type === 'grab' && action.prep) chef.intents.set(holdingArms(state)[0].id, action.prep);
  return action;
}

/** Plays a night with the chef at a fixed step until it ends or reaches `until` seconds. */
export function simulateNight(state, chef, until = Infinity, step = 1 / 60) {
  while (!state.over && state.time < until) {
    chefThink(state, chef, step);
    stepNight(state, step);
    state.events.length = 0;
  }
  return state;
}

