import { PALETTE } from '../config.js';
import { RECIPE } from '../data/recipes.js';
import { blob, oval, roundRect, TAU } from './draw.js';

args.text:
/**
 * Portraits of the bistro's regulars, drawn in code. Puffy inflates as her patience runs out,
 * so the portrait itself is her patience meter.
 */

import { PALETTE } from '../config.js';
import { blob, oval, TAU } from './draw.js';

const INK = PALETTE.ink;

/** Two cartoon eyes looking slightly toward the kitchen. */
function eyes(ctx, x, y, r, gap, look = 0.2, sleepy = false) {
  for (const side of [-1, 1]) {
    const ex = x + side * gap;
    blob(ctx, ex, y, r, '#ffffff', INK, 2);
    if (sleepy) {
      ctx.fillStyle = 'rgba(120,150,110,0.95)';
      ctx.beginPath();
      ctx.arc(ex, y, r, Math.PI, 0);
      ctx.fill();
      ctx.strokeStyle = INK;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(ex - r, y);
      ctx.lineTo(ex + r, y);
      ctx.stroke();
    }
    blob(ctx, ex + look * r, y + (sleepy ? r * 0.35 : 0.1 * r), r * 0.48, INK, null);
    blob(ctx, ex + look * r - r * 0.18, y - r * 0.2 + (sleepy ? r * 0.3 : 0), r * 0.16, '#ffffff', null);
  }
}

/** A small curved mouth; `mood` 1 is a smile, 0 a frown. */
function mouth(ctx, x, y, w, mood) {
  ctx.strokeStyle = INK;
  ctx.lineWidth = 2.2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  const curve = (mood - 0.45) * w * 0.9;
  ctx.moveTo(x - w / 2, y);
  ctx.quadraticCurveTo(x, y + curve, x + w / 2, y);
  ctx.stroke();
  ctx.lineCap = 'butt';
}

const PORTRAITS = {
  puffy(ctx, x, y, r, mood, t) {
    const puff = 1 + (1 - mood) * 0.32;
    const rr = r * 0.62 * puff;
    if (mood < 0.75) {
      ctx.fillStyle = '#d98b1e';
      const n = 14;
      const len = rr * (0.2 + (1 - mood) * 0.35);
      for (let i = 0; i < n; i++) {
        const a = (i / n) * TAU + t * 0.2;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(a - 0.12) * rr, y + Math.sin(a - 0.12) * rr);
        ctx.lineTo(x + Math.cos(a) * (rr + len), y + Math.sin(a) * (rr + len));
        ctx.lineTo(x + Math.cos(a + 0.12) * rr, y + Math.sin(a + 0.12) * rr);
        ctx.fill();
      }
    }
    ctx.fillStyle = '#ffd166';
    ctx.beginPath();
    ctx.moveTo(x - rr * 0.9, y);
    ctx.lineTo(x - rr * 1.35, y - rr * 0.35);
    ctx.lineTo(x - rr * 1.35, y + rr * 0.35);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = INK;
    ctx.lineWidth = 2;
    ctx.stroke();
    blob(ctx, x, y, rr, '#ffd166', INK, 2.5);
    ctx.fillStyle = '#fff3c4';
    ctx.beginPath();
    ctx.ellipse(x, y + rr * 0.35, rr * 0.7, rr * 0.45, 0, 0, Math.PI);
    ctx.fill();
    ctx.fillStyle = 'rgba(217,139,30,0.6)';
    for (const [dx, dy] of [[-0.4, -0.45], [0.1, -0.6], [0.45, -0.3]]) blob(ctx, x + dx * rr, y + dy * rr, rr * 0.1, 'rgba(217,139,30,0.6)', null);
    eyes(ctx, x + rr * 0.12, y - rr * 0.12, rr * 0.24, rr * 0.36, 0.3);
    mouth(ctx, x + rr * 0.15, y + rr * 0.42, rr * 0.34, mood);
  },
  shelby(ctx, x, y, r, mood, t, changed) {
    const shell = changed ? '#7fd1b9' : '#c9b8ff';
    ctx.save();
    ctx.translate(x + r * 0.2, y - r * 0.05);
    blob(ctx, 0, 0, r * 0.55, shell, INK, 2.5);
    ctx.strokeStyle = INK;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let a = 0; a < TAU * 2.2; a += 0.2) {
      const rr = (r * 0.48 * a) / (TAU * 2.2);
      ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
    }
    ctx.stroke();
    ctx.restore();
    blob(ctx, x - r * 0.25, y + r * 0.2, r * 0.36, '#ef5b4c', INK, 2.5);
    for (const side of [-1, 1]) {
      ctx.strokeStyle = INK;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x - r * 0.25 + side * r * 0.12, y);
      ctx.lineTo(x - r * 0.25 + side * r * 0.2, y - r * 0.28);
      ctx.stroke();
    }
    eyes(ctx, x - r * 0.25, y - r * 0.32, r * 0.13, r * 0.2, 0.2);
    oval(ctx, x - r * 0.68, y + r * 0.34, r * 0.2, r * 0.14, '#ef5b4c', INK, 2);
    mouth(ctx, x - r * 0.25, y + r * 0.3, r * 0.24, mood);
  },
  twins(ctx, x, y, r, mood, t) {
    for (const [dx, col, dir] of [[-0.3, '#ff9aa8', -1], [0.3, '#7fd1b9', 1]]) {
      const cx = x + dx * r;
      const bob = Math.sin(t * 2 + dx * 6) * r * 0.04;
      ctx.save();
      ctx.translate(cx, y + bob);
      ctx.scale(dir, 1);
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(-r * 0.05, -r * 0.55);
      ctx.quadraticCurveTo(r * 0.32, -r * 0.6, r * 0.28, -r * 0.3);
      ctx.lineTo(r * 0.42, -r * 0.24);
      ctx.lineTo(r * 0.26, -r * 0.14);
      ctx.quadraticCurveTo(r * 0.24, r * 0.1, r * 0.05, r * 0.2);
      ctx.quadraticCurveTo(r * 0.2, r * 0.5, -r * 0.05, r * 0.62);
      ctx.quadraticCurveTo(-r * 0.2, r * 0.45, -r * 0.06, r * 0.35);
      ctx.quadraticCurveTo(-r * 0.25, r * 0.05, -r * 0.05, -r * 0.55);
      ctx.closePath();
      ctx.fill();
      ctx.lineWidth = 2;
      ctx.strokeStyle = INK;
      ctx.stroke();
      blob(ctx, r * 0.1, -r * 0.36, r * 0.08, '#ffffff', INK, 1.5);
      blob(ctx, r * 0.12, -r * 0.36, r * 0.04, INK, null);
      ctx.restore();
    }
    mouth(ctx, x, y + r * 0.62, r * 0.2, mood);
  },
  tortuga(ctx, x, y, r, mood) {
    oval(ctx, x + r * 0.2, y + r * 0.35, r * 0.62, r * 0.36, '#5b8c4a', INK, 2.5);
    ctx.strokeStyle = 'rgba(30,60,30,0.6)';
    ctx.lineWidth = 2;
    for (const dx of [-0.2, 0.2, 0.55]) {
      ctx.beginPath();
      ctx.arc(x + dx * r, y + r * 0.35, r * 0.16, 0, TAU);
      ctx.stroke();
    }
    oval(ctx, x - r * 0.22, y - r * 0.08, r * 0.42, r * 0.38, '#9ccf7f', INK, 2.5);
    ctx.strokeStyle = 'rgba(40,80,40,0.5)';
    ctx.beginPath();
    ctx.arc(x - r * 0.22, y + r * 0.18, r * 0.2, Math.PI * 1.15, Math.PI * 1.85);
    ctx.stroke();
    eyes(ctx, x - r * 0.24, y - r * 0.18, r * 0.12, r * 0.18, 0.2, true);
    ctx.strokeStyle = INK;
    ctx.lineWidth = 2;
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.arc(x - r * 0.24 + side * r * 0.18, y - r * 0.18, r * 0.15, 0, TAU);
      ctx.stroke();
    }
    mouth(ctx, x - r * 0.24, y + r * 0.08, r * 0.26, Math.max(0.5, mood));
  },
  mantis(ctx, x, y, r, mood, t) {
    const g = ctx.createLinearGradient(x - r, y - r, x + r, y + r);
    g.addColorStop(0, '#ff7a59');
    g.addColorStop(0.5, '#5fd38d');
    g.addColorStop(1, '#5aa9e6');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(x, y + r * 0.2, r * 0.48, r * 0.42, 0, 0, TAU);
    ctx.fill();
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = INK;
    ctx.stroke();
    for (const side of [-1, 1]) {
      const ex = x + side * r * 0.28;
      const ey = y - r * 0.48 + Math.sin(t * 3 + side) * r * 0.03;
      ctx.strokeStyle = INK;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x + side * r * 0.12, y - r * 0.05);
      ctx.lineTo(ex, ey);
      ctx.stroke();
      oval(ctx, ex, ey, r * 0.16, r * 0.12, '#3b2a4d', INK, 2);
      ctx.fillStyle = '#7ff0ff';
      ctx.fillRect(ex - r * 0.16, ey - r * 0.02, r * 0.32, r * 0.04);
    }
    ctx.strokeStyle = '#ffd166';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x + r * 0.28, y - r * 0.48, r * 0.2, 0, TAU);
    ctx.stroke();
    ctx.fillStyle = '#3b2a4d';
    ctx.beginPath();
    ctx.ellipse(x - r * 0.05, y - r * 0.12, r * 0.34, r * 0.1, -0.15, 0, TAU);
    ctx.fill();
    blob(ctx, x - r * 0.05, y - r * 0.2, r * 0.06, '#3b2a4d', null);
    mouth(ctx, x, y + r * 0.28, r * 0.3, mood);
  },
};

/** Draws a customer's portrait in a round frame of radius r; `mood` is the patience share 0..1. */
export function drawCustomer(ctx, customerId, x, y, r, mood = 1, t = 0, changed = false) {
  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  const g = ctx.createRadialGradient(x, y - r * 0.3, r * 0.1, x, y, r);
  g.addColorStop(0, '#1d6f7a');
  g.addColorStop(1, '#0b3a42');
  ctx.fillStyle = g;
  ctx.fill();
  if (customerId !== 'puffy') ctx.clip();
  PORTRAITS[customerId](ctx, x, y, r, mood, t, changed);
  ctx.restore();
}

/**
 * Octavia herself: her mantle, chef's toque, eyes that follow the work, and eight tentacles
 * drawn as tapered bezier curves with suckers, reaching from her body to the stations.
 */

import { LAYOUT, PALETTE } from '../config.js';
import { ARM_REST, ARM_ROOTS } from '../arms.js';
import { blob, TAU } from './draw.js';
import { drawIngredient } from './food.js';

const SKIN = '#ff8a7a';
const SKIN_DARK = '#d9534f';
const BELLY = '#ffc9b9';

/** Smoothed tip positions the renderer animates toward each arm's logical target. */
export function createArmView() {
  return ARM_REST.map((p) => ({ x: p.x, y: p.y }));
}

/** Moves each drawn tip toward its arm's target, adding chop, stir and idle motion. */
export function updateArmView(view, state, dt, t, calm = false) {
  state.arms.forEach((arm, i) => {
    let { x, y } = arm.target;
    const sway = calm ? 0 : 1;
    if (arm.state === 'chop') y += Math.abs(Math.sin(t * 14)) * -16;
    else if (arm.state === 'stir') {
      x += Math.cos(t * 6 + i) * 16 * sway;
      y += Math.sin(t * 6 + i) * 6 * sway;
    } else if (arm.state === 'idle' && arm.reach <= 0) {
      x += Math.sin(t * 1.3 + i * 1.7) * 7 * sway;
      y += Math.cos(t * 1.1 + i) * 5 * sway;
    } else if (arm.state === 'hold' && arm.reach <= 0) y += Math.sin(t * 2 + i) * 3 * sway;
    const k = Math.min(1, dt * (arm.reach > 0 ? 16 : 9));
    view[i].x += (x - view[i].x) * k;
    view[i].y += (y - view[i].y) * k;
  });
}

/** Samples a cubic bezier at u. */
function bez(p0, p1, p2, p3, u) {
  const m = 1 - u;
  return {
    x: m * m * m * p0.x + 3 * m * m * u * p1.x + 3 * m * u * u * p2.x + u * u * u * p3.x,
    y: m * m * m * p0.y + 3 * m * m * u * p1.y + 3 * m * u * u * p2.y + u * u * u * p3.y,
  };
}

/** One tentacle from its root to its tip, tapering, with a pale underside and suckers. */
function drawTentacle(ctx, root, tip, i, t) {
  const side = i < 4 ? -1 : 1;
  const c1 = { x: root.x + side * 12, y: root.y + 60 };
  const c2 = { x: tip.x - (tip.x - root.x) * 0.2, y: tip.y - 46 + Math.sin(t * 2 + i) * 6 };
  const n = 22;
  const pts = [];
  for (let k = 0; k <= n; k++) pts.push(bez(root, c1, c2, tip, k / n));
  const left = [];
  const right = [];
  for (let k = 0; k <= n; k++) {
    const a = pts[Math.max(0, k - 1)];
    const b = pts[Math.min(n, k + 1)];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    const w = 15 - (k / n) * 10.5;
    left.push({ x: pts[k].x - (dy / len) * w, y: pts[k].y + (dx / len) * w });
    right.push({ x: pts[k].x + (dy / len) * w, y: pts[k].y - (dx / len) * w });
  }
  ctx.beginPath();
  ctx.moveTo(left[0].x, left[0].y);
  for (const p of left) ctx.lineTo(p.x, p.y);
  ctx.arc(tip.x, tip.y, 4.5, 0, TAU);
  for (let k = n; k >= 0; k--) ctx.lineTo(right[k].x, right[k].y);
  ctx.closePath();
  ctx.fillStyle = SKIN;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = PALETTE.ink;
  ctx.stroke();
  ctx.strokeStyle = BELLY;
  ctx.lineWidth = 4;
  ctx.beginPath();
  for (let k = 2; k <= n; k++) {
    const p = { x: (pts[k].x * 2 + right[k].x) / 3, y: (pts[k].y * 2 + right[k].y) / 3 };
    if (k === 2) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  }
  ctx.stroke();
  for (let k = 4; k < n; k += 3) {
    const p = { x: (pts[k].x + right[k].x * 2) / 3, y: (pts[k].y + right[k].y * 2) / 3 };
    blob(ctx, p.x, p.y, 3.2 - (k / n) * 1.6, '#ffe1d6', 'rgba(59,42,77,0.55)', 1.2);
  }
}

/** A tiny shell knife for the chopping arm. */
function knife(ctx, x, y) {
  ctx.fillStyle = '#e6f4f1';
  ctx.beginPath();
  ctx.moveTo(x - 4, y - 2);
  ctx.lineTo(x + 26, y + 6);
  ctx.lineTo(x - 2, y + 10);
  ctx.closePath();
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = PALETTE.ink;
  ctx.stroke();
}

/** A small ladle for a stirring arm. */
function ladle(ctx, x, y) {
  ctx.strokeStyle = '#8a5a34';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(x, y - 6);
  ctx.lineTo(x + 6, y + 22);
  ctx.stroke();
  blob(ctx, x + 7, y + 24, 6, '#c8a26b', PALETTE.ink, 2);
}

/** Octavia's mantle, toque and face; she looks toward `look`. */
function drawBody(ctx, look, t, blink) {
  const { x } = LAYOUT.octavia;
  const y = LAYOUT.octavia.y - 26;
  const g = ctx.createRadialGradient(x - 22, y - 34, 10, x, y + 10, 96);
  g.addColorStop(0, '#ffb3a3');
  g.addColorStop(0.55, SKIN);
  g.addColorStop(1, SKIN_DARK);
  ctx.beginPath();
  ctx.moveTo(x - 72, y + 30);
  ctx.bezierCurveTo(x - 92, y - 70, x + 92, y - 70, x + 72, y + 30);
  ctx.bezierCurveTo(x + 66, y + 70, x - 66, y + 70, x - 72, y + 30);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.lineWidth = 3.5;
  ctx.strokeStyle = PALETTE.ink;
  ctx.stroke();
  for (const [dx, dy, r] of [[-40, -22, 7], [34, -34, 5], [48, 4, 6], [-52, 10, 4], [14, -48, 4]]) blob(ctx, x + dx, y + dy, r, 'rgba(255,214,200,0.85)', null);
  const tx = x;
  const ty = y - 58;
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(tx - 26, ty - 14, 20, 0, TAU);
  ctx.arc(tx, ty - 26, 24, 0, TAU);
  ctx.arc(tx + 26, ty - 14, 20, 0, TAU);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(tx - 36, ty - 12, 72, 22);
  ctx.strokeRect(tx - 36, ty - 12, 72, 22);
  ctx.fillStyle = PALETTE.coral;
  ctx.fillRect(tx - 36, ty + 2, 72, 6);
  const dx = Math.max(-1, Math.min(1, (look.x - x) / 300));
  const dy = Math.max(-1, Math.min(1, (look.y - y) / 300));
  for (const side of [-1, 1]) {
    const ex = x + side * 27;
    const ey = y + 2;
    blob(ctx, ex, ey, 18, '#ffffff', PALETTE.ink, 3);
    if (blink) {
      ctx.fillStyle = SKIN;
      ctx.beginPath();
      ctx.arc(ex, ey, 18, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = PALETTE.ink;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(ex - 12, ey + 2);
      ctx.quadraticCurveTo(ex, ey + 8, ex + 12, ey + 2);
      ctx.stroke();
    } else {
      blob(ctx, ex + dx * 7, ey + dy * 6, 9, PALETTE.ink, null);
      blob(ctx, ex + dx * 7 - 3, ey + dy * 6 - 4, 3.2, '#ffffff', null);
    }
  }
  blob(ctx, x - 48, y + 26, 9, 'rgba(255,90,110,0.35)', null);
  blob(ctx, x + 48, y + 26, 9, 'rgba(255,90,110,0.35)', null);
  ctx.strokeStyle = PALETTE.ink;
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(x, y + 26 + Math.sin(t * 1.5) * 1, 13, 0.2, Math.PI - 0.2);
  ctx.stroke();
  ctx.lineCap = 'butt';
}

/**
 * Draws Octavia with every arm: tentacles behind the counter edge reach to their tips, holding
 * arms show their item, chopping and stirring arms carry a knife or a ladle.
 */
export function drawOctavia(ctx, state, view, t) {
  const busy = state.arms.filter((a) => a.state !== 'idle' || a.reach > 0);
  const look = busy.length ? busy.reduce((p, a) => (a.heldAt > p.heldAt ? a : p), busy[0]).target : { x: 640, y: 520 };
  const blink = Math.sin(t * 0.9) > 0.985;
  drawBody(ctx, look, t, blink);
  const order = state.arms.map((a, i) => i).sort((a, b) => view[a].y - view[b].y);
  for (const i of order) drawTentacle(ctx, ARM_ROOTS[i], view[i], i, t);
  for (const i of order) {
    const arm = state.arms[i];
    const tip = view[i];
    if (arm.state === 'hold' && arm.item) {
      drawIngredient(ctx, arm.item.ing, tip.x, tip.y - 14, 34, arm.item.prep, t);
      ctx.strokeStyle = SKIN_DARK;
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.arc(tip.x, tip.y - 8, 10, 0.3, Math.PI - 0.3);
      ctx.stroke();
      ctx.lineCap = 'butt';
      if (arm.item.quality === 'perfect') {
        ctx.strokeStyle = 'rgba(127,240,255,0.9)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(tip.x, tip.y - 14, 22 + Math.sin(t * 6) * 2, 0, TAU);
        ctx.stroke();
      }
    } else if (arm.state === 'chop') knife(ctx, tip.x, tip.y);
    else if (arm.state === 'stir') ladle(ctx, tip.x, tip.y);
  }
}

/**
 * The kitchen inside the giant clam: coral-tile wall with caustic light, the porthole, the
 * menu slate, the counter, every cooking station with its food and timing ring, the Clam
 * Plate, the Current Window and the ingredient bins.
 */

import { LAYOUT, PALETTE, SLOT_TARGETS, TUNING } from '../config.js';
import { INGREDIENTS } from '../data/ingredients.js';
import { RECIPE } from '../data/recipes.js';
import { CUSTOMERS } from '../data/customers.js';
import { cookProgress, isStirred, windowLeft } from '../stations.js';
import { patienceShare, ticketForPlate } from '../orders.js';
import { blob, keycap, label, oval, panel, ring, roundRect, TAU, text } from './draw.js';
import { drawDish, drawFinishedDish, drawIngredient } from './food.js';

const INK = PALETTE.ink;

/** Wall tiles, caustic ripples, the porthole with passing fish, a shelf and the menu slate. */
export function drawWall(ctx, state, t, calm) {
  const g = ctx.createLinearGradient(0, 140, 0, LAYOUT.wallBottom);
  g.addColorStop(0, '#0b3239');
  g.addColorStop(1, '#14525b');
  ctx.fillStyle = g;
  ctx.fillRect(0, 140, 1280, LAYOUT.wallBottom - 140);
  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 30; col++) {
      const x = col * 46 + (row % 2 ? 23 : 0) - 20;
      const y = 150 + row * 38;
      ctx.fillStyle = (row + col) % 3 === 0 ? 'rgba(127,209,185,0.10)' : (row * col) % 5 === 1 ? 'rgba(255,122,89,0.09)' : 'rgba(255,246,230,0.05)';
      roundRect(ctx, x, y, 42, 34, 9);
      ctx.fill();
    }
  }
  if (!calm) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(127,209,185,0.07)';
    ctx.lineWidth = 3;
    for (let k = 0; k < 9; k++) {
      ctx.beginPath();
      for (let x = 0; x <= 1280; x += 32) {
        const y = 170 + k * 34 + Math.sin(x * 0.012 + t * 0.9 + k) * 9 + Math.sin(x * 0.031 - t * 1.3) * 4;
        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.restore();
  }
  drawPorthole(ctx, t);
  drawShelf(ctx, t);
  drawMenuSlate(ctx, state);
}

/** A brass porthole with fish swimming past outside. */
function drawPorthole(ctx, t) {
  const { x, y, r } = LAYOUT.porthole;
  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  const sea = ctx.createLinearGradient(0, y - r, 0, y + r);
  sea.addColorStop(0, '#2a8fb0');
  sea.addColorStop(1, '#0b3d5c');
  ctx.fillStyle = sea;
  ctx.fill();
  ctx.clip();
  ctx.fillStyle = 'rgba(255,255,255,0.12)';
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(x - r + i * 40, y - r);
    ctx.lineTo(x - r + i * 40 + 30, y - r);
    ctx.lineTo(x - r + i * 40 - 10, y + r);
    ctx.lineTo(x - r + i * 40 - 30, y + r);
    ctx.fill();
  }
  for (let i = 0; i < 4; i++) {
    const fx = x - r - 30 + (((t * (18 + i * 7) + i * 60) % (r * 2 + 60)));
    const fy = y - 30 + i * 20 + Math.sin(t * 2 + i) * 5;
    const col = ['#ffd166', '#ff7a59', '#c9b8ff', '#7fd1b9'][i];
    oval(ctx, fx, fy, 12 - i, 6, col, INK, 1.5);
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.moveTo(fx - 10 + i, fy);
    ctx.lineTo(fx - 20 + i, fy - 6);
    ctx.lineTo(fx - 20 + i, fy + 6);
    ctx.closePath();
    ctx.fill();
    blob(ctx, fx + 6 - i, fy - 1, 1.6, INK, null);
  }
  ctx.strokeStyle = '#2e7d4f';
  ctx.lineWidth = 5;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(x - 40 + i * 34, y + r);
    ctx.quadraticCurveTo(x - 30 + i * 34 + Math.sin(t + i) * 10, y + 30, x - 36 + i * 34, y + 10);
    ctx.stroke();
  }
  ctx.restore();
  ctx.lineWidth = 12;
  ctx.strokeStyle = '#c99a4b';
  ctx.beginPath();
  ctx.arc(x, y, r + 5, 0, TAU);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.beginPath();
  ctx.arc(x, y, r + 11, 0, TAU);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(x, y, r - 1, 0, TAU);
  ctx.stroke();
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    blob(ctx, x + Math.cos(a) * (r + 5), y + Math.sin(a) * (r + 5), 3, '#f4d8a6', INK, 1.5);
  }
}

/** A driftwood shelf of jars and a kelp garland. */
function drawShelf(ctx, t) {
  ctx.fillStyle = '#8a5a34';
  roundRect(ctx, 318, 300, 250, 14, 5);
  ctx.fill();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = INK;
  ctx.stroke();
  const jars = [[346, '#7ff0ff', 'pearl'], [396, '#ff9aa8', 'salt'], [446, '#6fd3a8', 'grape'], [500, '#c9b8ff', 'jelly'], [546, '#ffd166', 'urchin']];
  for (const [x, col, ing] of jars) {
    ctx.fillStyle = 'rgba(214,240,245,0.35)';
    roundRect(ctx, x - 18, 254, 36, 46, 8);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = col;
    ctx.globalAlpha = 0.4;
    roundRect(ctx, x - 14, 272, 28, 24, 5);
    ctx.fill();
    ctx.globalAlpha = 1;
    drawIngredient(ctx, ing, x, 282, 20);
    ctx.fillStyle = '#c99a4b';
    roundRect(ctx, x - 14, 248, 28, 9, 3);
    ctx.fill();
    ctx.stroke();
  }
  ctx.strokeStyle = '#3e9a5c';
  ctx.lineWidth = 5;
  ctx.beginPath();
  for (let x = 300; x <= 590; x += 10) ctx.lineTo(x, 176 + Math.sin(x * 0.05) * 6 + (Math.abs(x - 445) / 145) * -12 + Math.sin(t + x) * 0.5);
  ctx.stroke();
  for (let x = 310; x <= 580; x += 34) blob(ctx, x, 184 + Math.sin(x * 0.05) * 6, 5, x % 68 ? '#ff7a59' : '#ffd166', INK, 1.5);
}

/** The menu slate on the wall: tonight's dishes. */
function drawMenuSlate(ctx, state) {
  const x = 716;
  const y = 166;
  const w = 190;
  const recipes = state.cfg.recipes;
  const h = 34 + recipes.length * 30;
  panel(ctx, x, y, w, h, { fill: '#1f3a3f', stroke: '#c99a4b', r: 10, line: 4 });
  text(ctx, `TONIGHT: ${state.cfg.name.toUpperCase()}`, x + w / 2, y + 24, { size: 14, color: PALETTE.gold, align: 'center', line: 3 });
  recipes.forEach((id, i) => {
    const ry = y + 46 + i * 30;
    drawFinishedDish(ctx, id, x + 24, ry, 34);
    label(ctx, RECIPE[id].name, x + 48, ry + 5, 14, PALETTE.pearl, 'left', 700);
  });
  if (state.cfg.critic.length) {
    drawFinishedDish(ctx, 'platter', x + 24, y + h + 4, 36);
    label(ctx, 'Grand Reef Platter (VIP)', x + 48, y + h + 9, 13, PALETTE.gold, 'left', 800);
  }
}

/** The sand-stone counter the stations stand on. */
export function drawCounter(ctx) {
  const top = LAYOUT.counterTop;
  const g = ctx.createLinearGradient(0, top, 0, LAYOUT.counterBottom);
  g.addColorStop(0, '#f4d8a6');
  g.addColorStop(1, '#d9b57a');
  ctx.fillStyle = g;
  ctx.fillRect(0, top, 1280, LAYOUT.counterBottom - top);
  ctx.fillStyle = 'rgba(255,246,230,0.6)';
  ctx.fillRect(0, top, 1280, 5);
  ctx.fillStyle = 'rgba(59,42,77,0.08)';
  for (let i = 0; i < 40; i++) blob(ctx, (i * 197) % 1280, top + 20 + ((i * 61) % 150), 2 + (i % 3), 'rgba(59,42,77,0.08)', null);
  ctx.fillStyle = '#6e4a2f';
  ctx.fillRect(0, LAYOUT.counterBottom, 1280, 800 - LAYOUT.counterBottom);
  ctx.fillStyle = '#5a3c26';
  for (let x = 0; x < 1280; x += 64) ctx.fillRect(x, LAYOUT.counterBottom, 3, 800 - LAYOUT.counterBottom);
  ctx.fillStyle = INK;
  ctx.fillRect(0, LAYOUT.counterBottom - 3, 1280, 4);
}

/** The ring over a cooking slot: blue while cooking, glowing green when perfect, orange, then smoke. */
function cookRing(ctx, item, x, y, t, r = 24) {
  if (!item) return;
  const p = cookProgress(item);
  if (item.phase === 'cook' || item.phase === 'chop') {
    ring(ctx, x, y, r, p, p > 0.85 ? PALETTE.gold : PALETTE.blue, 7, 'rgba(5,25,29,0.45)');
  } else if (item.phase === 'perfect') {
    const pulse = 0.5 + 0.5 * Math.sin(t * 10);
    ctx.save();
    ctx.shadowColor = PALETTE.green;
    ctx.shadowBlur = 14 + pulse * 10;
    ring(ctx, x, y, r, 1, PALETTE.green, 8, 'rgba(5,25,29,0.45)');
    ctx.restore();
    text(ctx, 'PERFECT', x, y - r - 10, { size: 15, color: '#c9ffd9', align: 'center', line: 4 });
  } else if (item.phase === 'over') {
    ring(ctx, x, y, r, 1, PALETTE.orange, 8, 'rgba(5,25,29,0.45)');
    text(ctx, 'HURRY', x, y - r - 10, { size: 14, color: PALETTE.orange, align: 'center', line: 4 });
  } else if (item.phase === 'flip') {
    const pulse = 0.5 + 0.5 * Math.sin(t * 14);
    ring(ctx, x, y, r, windowLeft(item) / TUNING.sear.flipWindow, PALETTE.gold, 8, 'rgba(5,25,29,0.45)');
    text(ctx, 'FLIP!', x, y - r - 10, { size: 18 + pulse * 3, color: PALETTE.gold, align: 'center', line: 5 });
  } else if (item.phase === 'burnt') {
    ring(ctx, x, y, r, 1, '#2b2b33', 8, 'rgba(5,25,29,0.45)');
    text(ctx, 'BURNT', x, y - r - 10, { size: 14, color: '#bbbbbb', align: 'center', line: 4 });
  }
}

/** Food in a station slot, darkened when burnt. */
function slotFood(ctx, item, x, y, s, t) {
  if (!item) return;
  const prep = item.phase === 'cook' && item.prep !== 'sear' ? null : item.phase === 'cook' && !item.flipped ? null : item.prep;
  ctx.save();
  if (item.phase === 'burnt') ctx.filter = 'brightness(0.35) saturate(0.4)';
  drawIngredient(ctx, item.ing, x, y, s, prep, t);
  ctx.restore();
}

/** A station's name plate with its hotkey. */
function stationLabel(ctx, name, key, x, y) {
  font14(ctx);
  const w = ctx.measureText(name).width + 46;
  panel(ctx, x - w / 2, y - 13, w, 26, { fill: PALETTE.deep, stroke: INK, r: 9, line: 2.5, shadow: false });
  label(ctx, name, x - 12, y + 5, 14, PALETTE.pearl, 'center', 800);
  keycap(ctx, key, x + w / 2 - 15, y, { size: 12 });
}

function font14(ctx) {
  ctx.font = `800 14px "Trebuchet MS", "Segoe UI", "Noto Sans", system-ui, sans-serif`;
}

/** The Shell Board: a scallop cutting board; chopping only moves while an arm works it. */
function drawBoard(ctx, state, t) {
  const st = LAYOUT.stations.board;
  const cx = st.x + st.w / 2;
  const cy = st.y + 64;
  ctx.beginPath();
  ctx.moveTo(cx - 92, cy);
  ctx.bezierCurveTo(cx - 96, cy - 66, cx + 96, cy - 66, cx + 92, cy);
  ctx.quadraticCurveTo(cx, cy + 22, cx - 92, cy);
  ctx.fillStyle = '#fff1d6';
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,122,89,0.45)';
  ctx.lineWidth = 3;
  for (let i = -3; i <= 3; i++) {
    ctx.beginPath();
    ctx.moveTo(cx, cy + 10);
    ctx.lineTo(cx + i * 28, cy - 44 + Math.abs(i) * 6);
    ctx.stroke();
  }
  const item = state.stations.board.slots[0];
  const at = SLOT_TARGETS.board[0];
  slotFood(ctx, item, at.x, at.y - 6, 44, t);
  if (item) cookRing(ctx, item, at.x + 62, at.y - 22, t, 16);
  const worker = state.arms.find((a) => a.state === 'chop');
  if (item && !worker) text(ctx, 'needs an arm', at.x, at.y + 28, { size: 13, color: PALETTE.gold, align: 'center', line: 3 });
  stationLabel(ctx, 'SHELL BOARD', 'Q', cx, st.y + st.h + 2);
}

/** A Bubble Pot on its vent stove; it burns twice as fast with no arm stirring. */
function drawPot(ctx, state, id, t) {
  const st = LAYOUT.stations[id];
  const cx = st.x + st.w / 2;
  const station = state.stations[id];
  if (station.locked) {
    ctx.setLineDash([8, 6]);
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(255,246,230,0.45)';
    roundRect(ctx, st.x + 10, st.y + 30, st.w - 20, st.h - 40, 18);
    ctx.stroke();
    ctx.setLineDash([]);
    text(ctx, 'SECOND POT', cx, st.y + 76, { size: 13, color: 'rgba(255,246,230,0.75)', align: 'center', line: 3 });
    text(ctx, 'upgrade', cx, st.y + 96, { size: 13, color: 'rgba(255,209,102,0.85)', align: 'center', line: 3 });
    return;
  }
  const item = station.slots[0];
  const vent = ctx.createRadialGradient(cx, st.y + st.h - 6, 4, cx, st.y + st.h - 6, 56);
  vent.addColorStop(0, item ? 'rgba(127,240,255,0.85)' : 'rgba(127,209,185,0.35)');
  vent.addColorStop(1, 'rgba(127,240,255,0)');
  ctx.fillStyle = vent;
  ctx.fillRect(st.x - 10, st.y + st.h - 50, st.w + 20, 60);
  ctx.fillStyle = '#2c3440';
  roundRect(ctx, st.x + 14, st.y + st.h - 22, st.w - 28, 22, 6);
  ctx.fill();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = INK;
  ctx.stroke();
  const body = ctx.createLinearGradient(st.x, 0, st.x + st.w, 0);
  body.addColorStop(0, '#2f8f9d');
  body.addColorStop(0.5, '#4fb7b0');
  body.addColorStop(1, '#1d6b66');
  ctx.beginPath();
  ctx.moveTo(st.x + 12, st.y + 46);
  ctx.lineTo(st.x + 18, st.y + st.h - 22);
  ctx.quadraticCurveTo(cx, st.y + st.h - 8, st.x + st.w - 18, st.y + st.h - 22);
  ctx.lineTo(st.x + st.w - 12, st.y + 46);
  ctx.closePath();
  ctx.fillStyle = body;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  oval(ctx, cx, st.y + 46, st.w / 2 - 10, 14, '#174f4b', INK, 3);
  if (item) {
    oval(ctx, cx, st.y + 47, st.w / 2 - 18, 9, item.phase === 'burnt' ? '#3a2f2f' : '#fbf3e4', null);
    slotFood(ctx, item, cx, st.y + 40, 38, t);
    const stirred = isStirred(state, id);
    if (item.phase !== 'cook' && !stirred && item.phase !== 'burnt') {
      text(ctx, 'STIR ME!', cx, st.y + st.h + 34, { size: 13, color: PALETTE.orange, align: 'center', line: 3 });
    }
  }
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#1d6b66';
    roundRect(ctx, cx + side * (st.w / 2 - 6) - 8, st.y + 56, 16, 10, 4);
    ctx.fill();
    ctx.stroke();
  }
  if (item) cookRing(ctx, item, cx, st.y + 6, t, 18);
  stationLabel(ctx, id === 'pot0' ? 'BUBBLE POT' : 'POT 2', id === 'pot0' ? 'W' : 'W', cx, st.y + st.h + 14);
}

/** The Vent Grill: a basalt slab over glowing lava cracks, two slots that each need a flip. */
function drawGrill(ctx, state, t) {
  const st = LAYOUT.stations.grill;
  ctx.fillStyle = '#3a2f3f';
  roundRect(ctx, st.x, st.y + 24, st.w, st.h - 30, 14);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  const glow = 0.6 + 0.4 * Math.sin(t * 3);
  ctx.strokeStyle = `rgba(255,122,61,${0.55 + glow * 0.35})`;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(st.x + 14, st.y + 70);
  ctx.lineTo(st.x + 48, st.y + 60);
  ctx.lineTo(st.x + 70, st.y + 78);
  ctx.lineTo(st.x + 110, st.y + 64);
  ctx.lineTo(st.x + 140, st.y + 80);
  ctx.lineTo(st.x + 176, st.y + 66);
  ctx.stroke();
  ctx.fillStyle = '#4a4050';
  roundRect(ctx, st.x + 8, st.y + 14, st.w - 16, 40, 10);
  ctx.fill();
  ctx.stroke();
  ctx.strokeStyle = 'rgba(20,10,10,0.7)';
  ctx.lineWidth = 3;
  for (let x = st.x + 20; x < st.x + st.w - 14; x += 16) {
    ctx.beginPath();
    ctx.moveTo(x, st.y + 20);
    ctx.lineTo(x, st.y + 48);
    ctx.stroke();
  }
  state.stations.grill.slots.forEach((item, i) => {
    const at = SLOT_TARGETS.grill[i];
    slotFood(ctx, item, at.x, at.y - 20, 42, t);
    if (item) cookRing(ctx, item, at.x, at.y - 46, t, 15);
  });
  stationLabel(ctx, 'VENT GRILL', 'E', st.x + st.w / 2, st.y + st.h + 2);
}

/** The Kelp Steamer: two woven baskets stacked under a lid, steaming. */
function drawSteamer(ctx, state, t) {
  const st = LAYOUT.stations.steamer;
  const cx = st.x + st.w / 2;
  ctx.fillStyle = '#b78a4e';
  ctx.beginPath();
  ctx.moveTo(st.x + 10, st.y + 30);
  ctx.quadraticCurveTo(cx, st.y - 10, st.x + st.w - 10, st.y + 30);
  ctx.closePath();
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  blob(ctx, cx, st.y + 8, 8, '#8a5a34', INK, 2.5);
  state.stations.steamer.slots.forEach((item, i) => {
    const y = st.y + 32 + i * 96;
    ctx.fillStyle = '#c8a26b';
    roundRect(ctx, st.x + 6, y, st.w - 12, 86, 14);
    ctx.fill();
    ctx.lineWidth = 3;
    ctx.strokeStyle = INK;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(110,74,47,0.55)';
    ctx.lineWidth = 2;
    for (let k = 1; k < 4; k++) {
      ctx.beginPath();
      ctx.moveTo(st.x + 10, y + k * 21);
      ctx.lineTo(st.x + st.w - 10, y + k * 21);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(30,25,20,0.55)';
    roundRect(ctx, st.x + 22, y + 14, st.w - 44, 58, 12);
    ctx.fill();
    const at = SLOT_TARGETS.steamer[i];
    slotFood(ctx, item, at.x - 14, at.y - 3, 42, t);
    if (item) cookRing(ctx, item, at.x + 44, at.y - 22, t, 15);
  });
  stationLabel(ctx, 'KELP STEAMER', 'R', cx, st.y + st.h + 12);
}

/** Every station, back to front. */
export function drawStations(ctx, state, t) {
  drawBoard(ctx, state, t);
  drawPot(ctx, state, 'pot0', t);
  drawPot(ctx, state, 'pot1', t);
  drawGrill(ctx, state, t);
  drawSteamer(ctx, state, t);
}

/** The Clam Plate: an open giant clam holding the dish being assembled. */
export function drawClamPlate(ctx, state, t) {
  const { x, y, w } = LAYOUT.plate;
  ctx.beginPath();
  ctx.moveTo(x - w / 2, y - 6);
  ctx.bezierCurveTo(x - w / 2, y - 92, x + w / 2, y - 92, x + w / 2, y - 6);
  ctx.closePath();
  const inner = ctx.createRadialGradient(x, y - 30, 10, x, y - 20, w / 2);
  inner.addColorStop(0, '#fff6e6');
  inner.addColorStop(1, '#c9b8ff');
  ctx.fillStyle = inner;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(59,42,77,0.25)';
  for (let i = -4; i <= 4; i++) {
    ctx.beginPath();
    ctx.moveTo(x, y - 6);
    ctx.lineTo(x + i * 26, y - 64 + Math.abs(i) * 7);
    ctx.stroke();
  }
  oval(ctx, x, y + 6, w / 2 + 6, 30, '#9ad9c6', INK, 3);
  const plate = state.plate;
  if (plate.recipeId) {
    drawDish(ctx, plate.recipeId, x, y - 6, 180, plate.parts, false);
  } else {
    label(ctx, 'Hold food, then press Space', x, y + 10, 13, 'rgba(59,42,77,0.7)', 'center', 800);
  }
  const lw = 196;
  panel(ctx, x - lw / 2, y + 26, lw, 26, { fill: PALETTE.deep, stroke: INK, r: 9, line: 2.5, shadow: false });
  label(ctx, 'CLAM PLATE', x - 20, y + 44, 14, PALETTE.pearl, 'center', 800);
  keycap(ctx, 'Space', x + 58, y + 39, { size: 12 });
  if (plate.recipeId) {
    const glow = 0.5 + 0.5 * Math.sin(t * 4);
    ctx.strokeStyle = `rgba(255,209,102,${0.25 + glow * 0.3})`;
    ctx.lineWidth = 3;
    oval(ctx, x, y + 6, w / 2 + 12, 34, null, `rgba(255,209,102,${0.25 + glow * 0.3})`, 3);
  }
}

/** The Current Window: the pass where finished plates glow until they are served. */
export function drawPass(ctx, state, t) {
  const p = LAYOUT.pass;
  panel(ctx, p.x, p.y, p.w, p.h, { fill: '#123f46', stroke: '#c99a4b', r: 24, line: 5 });
  ctx.save();
  roundRect(ctx, p.x + 8, p.y + 40, p.w - 16, p.h - 50, 18);
  ctx.clip();
  const water = ctx.createLinearGradient(0, p.y, 0, p.y + p.h);
  water.addColorStop(0, '#1c7488');
  water.addColorStop(1, '#0b3d4c');
  ctx.fillStyle = water;
  ctx.fillRect(p.x, p.y, p.w, p.h);
  ctx.strokeStyle = 'rgba(127,240,255,0.22)';
  ctx.lineWidth = 3;
  for (let i = 0; i < 12; i++) {
    const yy = p.y + 60 + i * 38;
    const off = (t * 60 + i * 47) % 260;
    ctx.beginPath();
    ctx.moveTo(p.x - 40 + off, yy);
    ctx.quadraticCurveTo(p.x + off, yy - 8, p.x + 40 + off, yy);
    ctx.stroke();
  }
  ctx.restore();
  text(ctx, 'CURRENT WINDOW', p.x + p.w / 2, p.y + 28, { size: 15, color: PALETTE.gold, align: 'center', line: 4 });
  const slots = state.upgrades.biggerPlate ? TUNING.biggerPassSlots : TUNING.passSlots;
  for (let i = 0; i < slots; i++) {
    const cy = p.y + 120 + i * 128;
    const plate = state.pass[i];
    oval(ctx, p.x + p.w / 2, cy + 26, 74, 18, 'rgba(255,246,230,0.12)', 'rgba(255,246,230,0.35)', 2);
    if (!plate) {
      label(ctx, 'empty', p.x + p.w / 2, cy + 30, 13, 'rgba(255,246,230,0.45)', 'center', 700);
      continue;
    }
    const pulse = 0.5 + 0.5 * Math.sin(t * 5 + i);
    ctx.save();
    ctx.shadowColor = PALETTE.gold;
    ctx.shadowBlur = 18 + pulse * 14;
    blob(ctx, p.x + p.w / 2, cy + 6, 62, `rgba(255,209,102,${0.16 + pulse * 0.12})`, null);
    ctx.restore();
    drawFinishedDish(ctx, plate.recipeId, p.x + p.w / 2, cy + 10, 150);
    const warm = plate.warmth / plate.maxWarmth;
    ctx.fillStyle = 'rgba(5,25,29,0.6)';
    roundRect(ctx, p.x + 24, cy + 48, p.w - 48, 8, 4);
    ctx.fill();
    ctx.fillStyle = warm > 0.35 ? PALETTE.coral : '#9fc7d6';
    roundRect(ctx, p.x + 24, cy + 48, (p.w - 48) * warm, 8, 4);
    ctx.fill();
    const ticket = ticketForPlate(state, plate);
    const dest = ticket ? `${CUSTOMERS[ticket.customerId].name} #${ticket.id}` : 'nobody ordered';
    text(ctx, RECIPE[plate.recipeId].name, p.x + p.w / 2, cy - 44, { size: 14, color: PALETTE.pearl, align: 'center', line: 3, maxWidth: p.w - 20 });
    if (i === 0 && ticket) {
      keycap(ctx, 'S', p.x + 22, cy + 76, { size: 13, fill: PALETTE.gold });
      text(ctx, `serve to ${dest}`, p.x + 36, cy + 81, { size: 13, color: PALETTE.pearl, line: 3, maxWidth: p.w - 40 });
    } else {
      text(ctx, ticket ? `for ${dest}` : dest, p.x + p.w / 2, cy + 81, { size: 13, color: ticket ? PALETTE.pearl : PALETTE.orange, align: 'center', line: 3, maxWidth: p.w - 16 });
    }
    if (ticket) {
      const share = patienceShare(ticket);
      ring(ctx, p.x + p.w - 22, cy - 22, 10, share, share > 0.5 ? PALETTE.green : share > 0.25 ? PALETTE.gold : PALETTE.red, 4);
    }
  }
}

/** The ten ingredient bins along the counter front, each with its name and hotkey. */
export function drawBins(ctx, t, hover = null) {
  const b = LAYOUT.bins;
  INGREDIENTS.forEach((ing, i) => {
    const x = b.x + i * (b.w + b.gap);
    const lifted = hover === i ? -4 : 0;
    panel(ctx, x, b.y + lifted, b.w, b.h, { fill: '#8a5a34', stroke: INK, r: 12, line: 3 });
    ctx.fillStyle = '#5a3c26';
    roundRect(ctx, x + 7, b.y + 8 + lifted, b.w - 14, 64, 10);
    ctx.fill();
    ctx.fillStyle = ing.color;
    ctx.globalAlpha = 0.28;
    roundRect(ctx, x + 7, b.y + 8 + lifted, b.w - 14, 64, 10);
    ctx.fill();
    ctx.globalAlpha = 1;
    const cx = x + b.w / 2;
    drawIngredient(ctx, ing.id, cx - 18, b.y + 50 + lifted, 34, null, t);
    drawIngredient(ctx, ing.id, cx + 18, b.y + 48 + lifted, 34, null, t);
    drawIngredient(ctx, ing.id, cx, b.y + 36 + lifted, 40, null, t);
    keycap(ctx, ing.key, x + 18, b.y + 18 + lifted, { size: 14, fill: PALETTE.gold });
    const words = ing.name.split(/[ -]/);
    const lines = ing.name.length > 11 ? [words.slice(0, -1).join(ing.name.includes('-') ? '-' : ' '), words[words.length - 1]] : [ing.name];
    lines.forEach((line, k) => {
      text(ctx, line, cx, b.y + 96 + k * 18 + (lines.length === 1 ? 8 : 0) + lifted, { size: 15, color: PALETTE.pearl, align: 'center', line: 3, maxWidth: b.w - 8 });
    });
  });
}

/** The ink jar that takes burnt food, mistakes and unwanted plates. */
export function drawTrash(ctx) {
  const tr = LAYOUT.trash;
  const cx = tr.x + tr.w / 2;
  ctx.fillStyle = '#5a4470';
  roundRect(ctx, tr.x + 8, tr.y + 14, tr.w - 16, 54, 14);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  oval(ctx, cx, tr.y + 16, tr.w / 2 - 6, 9, '#2a1d38', INK, 3);
  blob(ctx, cx - 10, tr.y + 42, 7, 'rgba(255,255,255,0.18)', null);
  label(ctx, 'BIN', cx, tr.y + 50, 14, PALETTE.pearl, 'center', 900);
  keycap(ctx, 'Bksp', cx, tr.y + 78, { size: 11 });
}

/**
 * The service HUD: the Current Board of shell tickets, the tide-clock timer, coins and Ink
 * Streak, the eight arm slots, the plate checklist, the Spring Tide gauge, key hints, toasts
 * and banners.
 */

import { ARM_COUNT, LAYOUT, PALETTE } from '../config.js';
import { CUSTOMERS } from '../data/customers.js';
import { INGREDIENT } from '../data/ingredients.js';
import { RECIPE } from '../data/recipes.js';
import { PREPS } from '../data/ingredients.js';
import { missingParts, patienceShare } from '../orders.js';
import { nextStreakTier, streakMultiplier } from '../scoring.js';
import { check, clock, keycap, label, panel, ring, roundRect, starRow, TAU, text } from './draw.js';
import { drawCustomer } from './customers.js';
import { drawFinishedDish, drawIngredient } from './food.js';

const INK = PALETTE.ink;

/** Colour of a patience share: green, gold, then red. */
export function patienceColor(share) {
  return share > 0.55 ? PALETTE.green : share > 0.28 ? PALETTE.gold : PALETTE.red;
}

/** The rail of shell-shaped tickets across the top. */
export function drawOrderBoard(ctx, state, t) {
  const b = LAYOUT.board;
  panel(ctx, 12, b.y, 120, b.h, { fill: '#5a3c26', stroke: INK, r: 14, line: 3 });
  text(ctx, 'CURRENT', 72, b.y + 36, { size: 18, color: PALETTE.gold, align: 'center', line: 4 });
  text(ctx, 'BOARD', 72, b.y + 58, { size: 18, color: PALETTE.gold, align: 'center', line: 4 });
  label(ctx, `${state.tickets.length} waiting`, 72, b.y + 84, 14, PALETTE.pearl, 'center', 800);
  keycap(ctx, 'Tab', 50, b.y + 110, { size: 12 });
  label(ctx, 'next', 86, b.y + 115, 13, PALETTE.pearl, 'center', 800);
  ctx.strokeStyle = '#c8a26b';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(b.x, b.y + 16);
  for (let x = b.x; x <= b.x + b.w; x += 20) ctx.lineTo(x, b.y + 16 + Math.sin(x * 0.05) * 2);
  ctx.stroke();
  const tk = LAYOUT.ticket;
  state.tickets.slice(0, tk.max).forEach((ticket, i) => {
    drawTicket(ctx, state, ticket, tk.x + i * (tk.w + tk.gap), tk.y, t);
  });
  if (state.tickets.length > tk.max) {
    text(ctx, `+${state.tickets.length - tk.max}`, b.x + b.w - 6, b.y + 80, { size: 20, color: PALETTE.gold, align: 'right' });
  }
  for (let i = 0; i < state.tickets.length - 1 && i < tk.max - 1; i++) {
    const a = state.tickets[i];
    const c = state.tickets[i + 1];
    if (a.pairId !== null && a.pairId === c.pairId) {
      const x = tk.x + (i + 1) * (tk.w + tk.gap) - tk.gap / 2;
      ctx.strokeStyle = PALETTE.gold;
      ctx.lineWidth = 4;
      for (const dy of [-8, 8]) {
        ctx.beginPath();
        ctx.ellipse(x, tk.y + 60 + dy, 6, 9, 0, 0, TAU);
        ctx.stroke();
      }
    }
  }
}

/** One shell ticket: portrait with patience ring, dish, steps and ticket number. */
function drawTicket(ctx, state, ticket, x, y, t) {
  const tk = LAYOUT.ticket;
  const selected = ticket.id === state.selectedTicket;
  const share = patienceShare(ticket);
  const recipe = RECIPE[ticket.recipeId];
  const lift = selected ? -4 : 0;
  const shake = share < 0.2 ? Math.sin(t * 30) * 1.5 : 0;
  const tx = x + shake;
  const ty = y + lift;
  if (selected) {
    ctx.save();
    ctx.shadowColor = PALETTE.gold;
    ctx.shadowBlur = 16;
    panel(ctx, tx - 3, ty - 3, tk.w + 6, tk.h + 6, { fill: PALETTE.gold, stroke: PALETTE.gold, r: 16, line: 2, shadow: false });
    ctx.restore();
  }
  ctx.beginPath();
  ctx.moveTo(tx, ty + 14);
  for (let k = 0; k <= 6; k++) {
    const sx = tx + (k * tk.w) / 6;
    ctx.quadraticCurveTo(sx - tk.w / 12, ty - 2, sx, ty + 14);
  }
  ctx.lineTo(tx + tk.w, ty + tk.h - 12);
  ctx.quadraticCurveTo(tx + tk.w, ty + tk.h, tx + tk.w - 12, ty + tk.h);
  ctx.lineTo(tx + 12, ty + tk.h);
  ctx.quadraticCurveTo(tx, ty + tk.h, tx, ty + tk.h - 12);
  ctx.closePath();
  ctx.fillStyle = ticket.critic ? '#efe4ff' : '#fff6e6';
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = INK;
  ctx.stroke();
  ctx.fillStyle = ticket.critic ? '#5a4470' : PALETTE.coral;
  roundRect(ctx, tx + tk.w / 2 - 14, ty - 6, 28, 14, 5);
  ctx.fill();
  ctx.stroke();
  const pr = 22;
  const px = tx + 28;
  const py = ty + 40;
  drawCustomer(ctx, ticket.customerId, px, py, pr, share, t, ticket.changed);
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = INK;
  ctx.beginPath();
  ctx.arc(px, py, pr, 0, TAU);
  ctx.stroke();
  ring(ctx, px, py, pr + 5, share, patienceColor(share), 5, 'rgba(59,42,77,0.25)');
  label(ctx, `#${ticket.id}`, tx + tk.w - 8, ty + 26, 14, INK, 'right', 900);
  drawFinishedDish(ctx, ticket.recipeId, tx + tk.w - 42, ty + 54, 66);
  label(ctx, CUSTOMERS[ticket.customerId].name, tx + 8, ty + 78, 12, '#5a4470', 'left', 800);
  label(ctx, recipe.name, tx + 8, ty + 92, 13, INK, 'left', 900);
  const onPlate = state.plate.recipeId === ticket.recipeId ? state.plate.parts : [];
  const missing = missingParts(ticket.recipeId, onPlate);
  const steps = recipe.parts.length + 1;
  const sw = Math.min(22, (tk.w - 12) / steps);
  recipe.parts.forEach(([ing, prep], k) => {
    const sx = tx + 8 + k * sw + sw / 2;
    const sy = ty + tk.h - 10;
    const done = !missing.some(([i2, p2]) => i2 === ing && p2 === prep) && onPlate.length > 0;
    drawIngredient(ctx, ing, sx, sy, 17, prep, t);
    if (done) check(ctx, sx + 6, sy - 6, 5);
  });
  const fx = tx + 8 + recipe.parts.length * sw + sw / 2;
  label(ctx, '+', fx, ty + tk.h - 5, 15, INK, 'center', 900);
  if (ticket.critic) {
    starRow(ctx, tx + tk.w / 2, ty + 9, 6, state.critic.live ?? 0);
  }
  if (ticket.changed && state.time - ticket.born < 999) {
    label(ctx, 'NEW ORDER', tx + tk.w - 8, ty + 40, 10, PALETTE.coralDark, 'right', 900);
  }
}

/** The tide-clock sand dial, night number, coins and Ink Streak. */
export function drawHud(ctx, state, t) {
  const h = LAYOUT.hud;
  panel(ctx, h.x, h.y, h.w, h.h, { fill: PALETTE.deep, stroke: '#c99a4b', r: 16, line: 4 });
  const left = Math.max(0, state.cfg.duration - state.time);
  const frac = left / state.cfg.duration;
  const cx = h.x + 62;
  const cy = h.y + h.h / 2;
  const r = 50;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, TAU);
  ctx.fillStyle = '#0a2a30';
  ctx.fill();
  ctx.clip();
  const level = cy + r - frac * r * 2;
  ctx.fillStyle = frac < 0.2 ? '#ef5b4c' : '#2f9fb3';
  ctx.beginPath();
  ctx.moveTo(cx - r, cy + r);
  for (let x = -r; x <= r; x += 6) ctx.lineTo(cx + x, level + Math.sin(x * 0.12 + t * 3) * 3);
  ctx.lineTo(cx + r, cy + r);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
  ctx.lineWidth = 6;
  ctx.strokeStyle = '#f4d8a6';
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, TAU);
  ctx.stroke();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = INK;
  ctx.beginPath();
  ctx.arc(cx, cy, r + 4, 0, TAU);
  ctx.stroke();
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a) * (r - 7), cy + Math.sin(a) * (r - 7));
    ctx.lineTo(cx + Math.cos(a) * (r - 1), cy + Math.sin(a) * (r - 1));
    ctx.stroke();
  }
  const hand = -Math.PI / 2 + (1 - frac) * TAU;
  ctx.strokeStyle = PALETTE.coral;
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(hand) * (r - 12), cy + Math.sin(hand) * (r - 12));
  ctx.stroke();
  ctx.lineCap = 'butt';
  text(ctx, clock(left), cx, cy + 10, { size: 28, color: PALETTE.pearl, align: 'center', line: 5 });
  const rx = h.x + 124;
  text(ctx, `NIGHT ${state.nightIndex + 1}/5`, rx, h.y + 26, { size: 15, color: PALETTE.gold, line: 3 });
  text(ctx, state.cfg.name, rx, h.y + 44, { size: 13, color: PALETTE.foam, line: 3, maxWidth: 108 });
  const coinX = rx + 12;
  ctx.fillStyle = PALETTE.gold;
  ctx.beginPath();
  ctx.arc(coinX, h.y + 70, 11, 0, TAU);
  ctx.fill();
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = INK;
  ctx.stroke();
  label(ctx, 'c', coinX, h.y + 75, 13, INK, 'center', 900);
  text(ctx, String(state.coins), rx + 30, h.y + 79, { size: 24, color: PALETTE.pearl, line: 4 });
  const mult = streakMultiplier(state.streak);
  const next = nextStreakTier(state.streak);
  const sx = rx;
  const sy = h.y + 104;
  const splat = mult > 1;
  ctx.fillStyle = splat ? '#5a4470' : 'rgba(90,68,112,0.5)';
  roundRect(ctx, sx - 2, sy - 12, 112, 30, 10);
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = splat ? PALETTE.gold : INK;
  ctx.stroke();
  text(ctx, `INK x${mult}`, sx + 6, sy + 9, { size: 17, color: splat ? PALETTE.gold : PALETTE.pearl, line: 3 });
  label(ctx, next ? `${state.streak}/${next}` : 'MAX', sx + 104, sy + 8, 12, PALETTE.pearl, 'right', 800);
  if (state.critic.live !== null || state.cfg.critic.length) {
    const reviews = state.critic.reviews;
    const shown = state.critic.live ?? (reviews.length ? reviews[reviews.length - 1] : 0);
    panel(ctx, h.x, h.y + h.h + 6, h.w, 30, { fill: '#3b2a4d', stroke: PALETTE.gold, r: 10, line: 2, shadow: false });
    label(ctx, 'CRITIC', h.x + 12, h.y + h.h + 27, 13, PALETTE.gold, 'left', 900);
    starRow(ctx, h.x + 150, h.y + h.h + 21, 9, shown);
  }
}

/** The eight arm slots: free, holding an item, chopping or stirring. */
export function drawArmSlots(ctx, state, t) {
  const a = LAYOUT.arms;
  panel(ctx, a.x, a.y, a.w, a.h, { fill: 'rgba(8,42,48,0.88)', stroke: INK, r: 14, line: 3 });
  const free = state.arms.filter((arm) => arm.state === 'idle').length;
  text(ctx, 'ARMS', a.x + a.w / 2, a.y + 22, { size: 16, color: PALETTE.gold, align: 'center', line: 3 });
  label(ctx, `${free}/${ARM_COUNT} free`, a.x + a.w / 2, a.y + 40, 13, free ? PALETTE.foam : PALETTE.red, 'center', 800);
  state.arms.forEach((arm, i) => {
    const y = a.y + 52 + i * 39;
    const busy = arm.state !== 'idle';
    ctx.fillStyle = busy ? '#ffb3a3' : 'rgba(255,246,230,0.1)';
    roundRect(ctx, a.x + 8, y, a.w - 16, 34, 10);
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = busy ? INK : 'rgba(255,246,230,0.25)';
    ctx.stroke();
    label(ctx, String(i + 1), a.x + 18, y + 22, 12, busy ? INK : 'rgba(255,246,230,0.5)', 'center', 900);
    if (arm.state === 'hold' && arm.item) {
      drawIngredient(ctx, arm.item.ing, a.x + 46, y + 18, 26, arm.item.prep, t);
      const tag = arm.item.prep === null ? 'raw' : arm.item.quality === 'perfect' ? 'perfect' : PREPS[arm.item.prep].label;
      label(ctx, tag, a.x + 64, y + 22, 10, arm.item.quality === 'perfect' ? '#1d7a4a' : INK, 'left', 900);
    } else if (arm.state === 'chop') {
      label(ctx, 'chopping', a.x + 58, y + 22, 12, INK, 'center', 900);
    } else if (arm.state === 'stir') {
      label(ctx, 'stirring', a.x + 58, y + 22, 12, INK, 'center', 900);
    } else {
      label(ctx, 'free', a.x + 58, y + 22, 12, 'rgba(255,246,230,0.55)', 'center', 800);
    }
  });
}

/** The plate checklist: which parts are on the Clam Plate and what is left. */
export function drawChecklist(ctx, state) {
  const c = LAYOUT.checklist;
  panel(ctx, c.x, c.y, c.w, c.h, { fill: PALETTE.pearl, stroke: INK, r: 14, line: 3 });
  const plate = state.plate;
  if (!plate.recipeId) {
    text(ctx, 'CLAM PLATE IS EMPTY', c.x + 14, c.y + 28, { size: 15, color: PALETTE.ink, outline: null });
    label(ctx, 'Grab with 1-0, cook with Q W E R, plate with Space', c.x + 14, c.y + 52, 13, '#5a4470', 'left', 700);
    label(ctx, 'S serves the glowing plate at the Current Window', c.x + 14, c.y + 70, 13, '#5a4470', 'left', 700);
    return;
  }
  const recipe = RECIPE[plate.recipeId];
  const steps = recipe.parts.length + 1;
  const done = plate.parts.length;
  text(ctx, `${recipe.name.toUpperCase()}  ${done}/${steps}`, c.x + 14, c.y + 25, { size: 16, color: PALETTE.coralDark, outline: null });
  const left = [...plate.parts];
  const chips = recipe.parts.map(([ing, prep]) => {
    const i = left.findIndex((p) => p.ing === ing && p.prep === prep);
    const has = i >= 0;
    if (has) left.splice(i, 1);
    const word = prep === 'raw' ? INGREDIENT[ing].name : `${INGREDIENT[ing].name.split(' ').pop()} ${PREPS[prep].label}`;
    return { word, has };
  });
  chips.push({ word: recipe.finish, has: false, finish: true });
  let x = c.x + 14;
  let y = c.y + 36;
  ctx.font = `800 12px "Trebuchet MS", "Noto Sans", sans-serif`;
  for (const chip of chips) {
    const w = ctx.measureText(chip.word).width + 30;
    if (x + w > c.x + c.w - 8) {
      x = c.x + 14;
      y += 20;
    }
    ctx.fillStyle = chip.has ? '#d4f5df' : chip.finish ? '#ffe3a3' : '#f0e6d6';
    roundRect(ctx, x, y, w, 18, 9);
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = INK;
    ctx.stroke();
    if (chip.has) check(ctx, x + 10, y + 9, 6);
    else {
      ctx.strokeStyle = INK;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x + 10, y + 9, 5, 0, TAU);
      ctx.stroke();
    }
    label(ctx, chip.word, x + 19, y + 13, 12, INK, 'left', 800);
    x += w + 6;
  }
}

/** The Spring Tide gauge: time to the next rush, or the rush running now. */
export function drawTideGauge(ctx, state, t) {
  const g = LAYOUT.tide;
  const r = state.rush;
  const next = state.cfg.rushes[r.index];
  const active = r.active;
  panel(ctx, g.x, g.y, g.w, g.h, { fill: active ? '#1d6f8a' : PALETTE.deep, stroke: active ? PALETTE.gold : INK, r: 14, line: 3 });
  ctx.save();
  roundRect(ctx, g.x + 4, g.y + 4, g.w - 8, g.h - 8, 11);
  ctx.clip();
  ctx.fillStyle = active ? 'rgba(127,240,255,0.25)' : 'rgba(127,209,185,0.12)';
  ctx.beginPath();
  ctx.moveTo(g.x, g.y + g.h);
  for (let x = 0; x <= g.w; x += 8) ctx.lineTo(g.x + x, g.y + g.h - 24 + Math.sin(x * 0.08 + t * 4) * 6);
  ctx.lineTo(g.x + g.w, g.y + g.h);
  ctx.fill();
  ctx.restore();
  if (active) {
    text(ctx, 'SPRING TIDE!', g.x + g.w / 2, g.y + 30, { size: 19, color: PALETTE.gold, align: 'center', line: 4 });
    label(ctx, `rush ends in ${clock(r.endsAt - state.time)}`, g.x + g.w / 2, g.y + 54, 13, PALETTE.pearl, 'center', 800);
  } else if (next !== undefined) {
    text(ctx, 'NEXT SPRING TIDE', g.x + g.w / 2, g.y + 28, { size: 14, color: PALETTE.foam, align: 'center', line: 3 });
    text(ctx, clock(next - state.time), g.x + g.w / 2, g.y + 56, { size: 22, color: PALETTE.pearl, align: 'center', line: 4 });
  } else {
    text(ctx, 'CALM WATERS', g.x + g.w / 2, g.y + 34, { size: 15, color: PALETTE.foam, align: 'center', line: 3 });
    label(ctx, 'no rush left tonight', g.x + g.w / 2, g.y + 56, 12, PALETTE.pearl, 'center', 700);
  }
}

/** The key hint card in the corner. */
export function drawKeyHints(ctx) {
  const k = LAYOUT.keys;
  panel(ctx, k.x, k.y, k.w, k.h, { fill: '#1f3a3f', stroke: INK, r: 12, line: 3 });
  const rows = [['1-0', 'grab'], ['QWER', 'stations'], ['Space', 'plate'], ['S', 'serve'], ['Bksp', 'bin'], ['P H M', 'pause help mute']];
  rows.forEach(([key, what], i) => {
    const y = k.y + 16 + i * 20;
    keycap(ctx, key, k.x + 10, y, { size: 11, align: 'left' });
    label(ctx, what, k.x + 66, y + 4, 12, PALETTE.pearl, 'left', 700);
  });
}

/** Short-lived messages above the plate. */
export function drawToasts(ctx, state) {
  state.toasts.forEach((toast, i) => {
    const age = state.time - toast.at;
    const alpha = Math.max(0, Math.min(1, 2.6 - age));
    ctx.globalAlpha = alpha;
    text(ctx, toast.text, 640, 530 - i * 22 - age * 8, { size: 17, color: toast.color, align: 'center', line: 5 });
    ctx.globalAlpha = 1;
  });
}

/** Big banners: the Spring Tide warning and start, and the night's opening card. */
export function drawBanners(ctx, state, t) {
  const r = state.rush;
  if (r.warnAt !== null && !r.active) {
    const pulse = 0.5 + 0.5 * Math.sin(t * 8);
    banner(ctx, 'SPRING TIDE INCOMING', `tickets will rush in ${clock(state.cfg.rushes[r.index] - state.time)}`, 0.85 + pulse * 0.15);
  } else if (r.active && state.time - (r.endsAt - 24) < 2.2) {
    banner(ctx, 'SPRING TIDE!', 'orders flood in: keep every arm busy', 1);
  }
  if (state.time < 3.2) {
    const alpha = Math.min(1, (3.2 - state.time) * 1.5);
    ctx.globalAlpha = alpha;
    banner(ctx, `NIGHT ${state.nightIndex + 1}: ${state.cfg.name.toUpperCase()}`, state.cfg.tip, 1);
    ctx.globalAlpha = 1;
  }
}

/** A wave-shaped banner across the kitchen wall. */
function banner(ctx, title, sub, scale) {
  const w = 620;
  const h = 76;
  const x = 640 - w / 2;
  const y = 196;
  ctx.save();
  ctx.translate(640, y + h / 2);
  ctx.scale(scale, scale);
  ctx.translate(-640, -(y + h / 2));
  panel(ctx, x, y, w, h, { fill: 'rgba(29,111,138,0.95)', stroke: PALETTE.gold, r: 22, line: 4 });
  text(ctx, title, 640, y + 36, { size: 28, color: PALETTE.gold, align: 'center', line: 6 });
  text(ctx, sub, 640, y + 62, { size: 15, color: PALETTE.pearl, align: 'center', line: 4, maxWidth: w - 30 });
  ctx.restore();
}

/**
 * Juice: bubbles, steam, sizzle sparks, chopping chips, ink puffs, coin pops and combo words,
 * spawned from the night's events and from the stations' live state.
 */

import { LAYOUT, PALETTE, SLOT_TARGETS } from '../config.js';
import { INGREDIENT } from '../data/ingredients.js';
import { blob, TAU, text } from './draw.js';

/** A fresh particle pool. */
export function createEffects() {
  return { list: [], shake: 0, flash: 0 };
}

function add(fx, p) {
  if (fx.list.length < 420) fx.list.push({ vx: 0, vy: 0, g: 0, life: 1, age: 0, size: 4, ...p });
}

function burst(fx, kind, x, y, n, opts = {}) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * TAU;
    const sp = (opts.speed ?? 80) * (0.4 + Math.random() * 0.8);
    add(fx, { kind, x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - (opts.up ?? 0), life: opts.life ?? 0.7, size: (opts.size ?? 4) * (0.6 + Math.random() * 0.8), color: opts.color, g: opts.g ?? 0 });
  }
}

/** Turns the night's events into particles and floating words. */
export function spawnFromEvents(fx, events, calm) {
  const n = calm ? 0.35 : 1;
  for (const e of events) {
    switch (e.type) {
      case 'grab': burst(fx, 'bubble', e.x, e.y - 20, Math.ceil(5 * n), { speed: 40, up: 50, life: 0.8, size: 4 }); break;
      case 'place': burst(fx, 'bubble', e.x, e.y, Math.ceil(6 * n), { speed: 60, up: 40, size: 4 }); break;
      case 'chop': burst(fx, 'chip', e.x, e.y - 4, Math.ceil(3 * n), { speed: 90, up: 60, g: 260, life: 0.5, size: 3.5, color: INGREDIENT.kelp.color }); break;
      case 'chopDone': add(fx, { kind: 'word', x: e.x, y: e.y - 40, vy: -30, life: 0.9, text: 'Chopped!', color: PALETTE.pearl, size: 18 }); break;
      case 'perfect': burst(fx, 'spark', e.x, e.y - 20, Math.ceil(12 * n), { speed: 120, life: 0.6, size: 3, color: PALETTE.green }); break;
      case 'flip': burst(fx, 'spark', e.x, e.y - 20, Math.ceil(14 * n), { speed: 150, up: 60, g: 200, life: 0.6, size: 3, color: PALETTE.orange });
        add(fx, { kind: 'word', x: e.x, y: e.y - 70, vy: -40, life: 0.8, text: 'Flip!', color: PALETTE.gold, size: 20 }); break;
      case 'burnt': burst(fx, 'smoke', e.x, e.y - 20, Math.ceil(8 * n), { speed: 30, up: 50, life: 1.4, size: 12 }); fx.shake = calm ? 0 : 4; break;
      case 'trash': burst(fx, 'ink', e.x, e.y, Math.ceil(10 * n), { speed: 70, life: 0.8, size: 9 }); break;
      case 'plateAdd': burst(fx, 'spark', e.x, e.y - 10, Math.ceil(6 * n), { speed: 80, life: 0.45, size: 3, color: PALETTE.gold }); break;
      case 'finish':
        add(fx, { kind: 'word', x: e.x, y: e.y - 70, vy: -36, life: 1.1, text: `${e.word}!`, color: PALETTE.gold, size: 30 });
        burst(fx, 'spark', e.x, e.y - 20, Math.ceil(18 * n), { speed: 160, life: 0.7, size: 3.5, color: PALETTE.gold }); break;
      case 'serve':
        add(fx, { kind: 'word', x: e.x, y: e.y - 60, vy: -46, life: 1.3, text: `+${e.coins}`, color: PALETTE.gold, size: 32 });
        if (e.mult > 1) add(fx, { kind: 'word', x: e.x - 30, y: e.y - 20, vy: -40, life: 1.3, text: `INK x${e.mult}`, color: '#d9b8ff', size: 22 });
        if (e.perfect) add(fx, { kind: 'word', x: e.x, y: e.y - 100, vy: -36, life: 1.2, text: 'PERFECT!', color: '#c9ffd9', size: 22 });
        for (let i = 0; i < Math.ceil(8 * n); i++) add(fx, { kind: 'coin', x: e.x + (Math.random() - 0.5) * 60, y: e.y, tx: LAYOUT.hud.x + 136, ty: LAYOUT.hud.y + 70, life: 0.9 + i * 0.05, size: 7 });
        break;
      case 'twinBonus': add(fx, { kind: 'word', x: e.x, y: e.y - 130, vy: -30, life: 1.4, text: `Twin bonus +${e.coins}`, color: PALETTE.foam, size: 20 }); break;
      case 'miss': fx.flash = calm ? 0 : 0.35; break;
      case 'streakBroken': add(fx, { kind: 'word', x: 1150, y: 170, vy: -20, life: 1.2, text: 'Streak lost', color: PALETTE.red, size: 18 }); break;
      case 'criticVerdict': add(fx, { kind: 'word', x: 640, y: 250, vy: -20, life: 2, text: `Madame Mantis: ${e.stars} stars`, color: PALETTE.gold, size: 26 }); break;
      case 'rushStart': fx.shake = calm ? 0 : 6; break;
      default: break;
    }
  }
}

/** Ambient bubbles, steam and sizzle from whatever the stations are doing. */
export function ambient(fx, state, dt, calm) {
  const rate = calm ? 0.3 : 1;
  const chance = (perSecond) => Math.random() < perSecond * dt * rate;
  for (const id of ['pot0', 'pot1']) {
    const item = state.stations[id].slots[0];
    if (item && item.phase !== 'burnt' && chance(item.phase === 'cook' ? 6 : 12)) {
      const at = SLOT_TARGETS[id][0];
      add(fx, { kind: 'bubble', x: at.x + (Math.random() - 0.5) * 70, y: at.y - 10, vy: -40 - Math.random() * 40, life: 0.9, size: 3 + Math.random() * 4 });
    }
  }
  state.stations.steamer.slots.forEach((item, i) => {
    if (item && chance(5)) {
      const at = SLOT_TARGETS.steamer[i];
      add(fx, { kind: 'steam', x: at.x + (Math.random() - 0.5) * 60, y: at.y - 40, vy: -30, vx: (Math.random() - 0.5) * 10, life: 1.4, size: 10 + Math.random() * 8 });
    }
  });
  state.stations.grill.slots.forEach((item, i) => {
    if (item && item.phase !== 'burnt' && chance(item.phase === 'flip' ? 14 : 7)) {
      const at = SLOT_TARGETS.grill[i];
      add(fx, { kind: 'spark', x: at.x + (Math.random() - 0.5) * 40, y: at.y - 18, vx: (Math.random() - 0.5) * 60, vy: -80 - Math.random() * 60, g: 220, life: 0.5, size: 2.5, color: Math.random() < 0.5 ? PALETTE.orange : PALETTE.gold });
    }
    if (item?.phase === 'burnt' && chance(5)) {
      const at = SLOT_TARGETS.grill[i];
      add(fx, { kind: 'smoke', x: at.x, y: at.y - 30, vy: -30, life: 1.4, size: 12 });
    }
  });
  if (chance(2.5)) add(fx, { kind: 'bubble', x: Math.random() * 1280, y: 470, vy: -30 - Math.random() * 30, life: 3.5, size: 2 + Math.random() * 3 });
}

/** Moves and ages particles. */
export function updateEffects(fx, dt) {
  for (const p of fx.list) {
    p.age += dt;
    if (p.kind === 'coin') {
      const k = Math.min(1, p.age / p.life);
      p.x += (p.tx - p.x) * Math.min(1, dt * 6 * (0.5 + k));
      p.y += (p.ty - p.y) * Math.min(1, dt * 6 * (0.5 + k));
      continue;
    }
    p.vy += p.g * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    if (p.kind === 'bubble') p.x += Math.sin(p.age * 6 + p.y) * 0.4;
  }
  fx.list = fx.list.filter((p) => p.age < p.life);
  fx.shake = Math.max(0, fx.shake - dt * 18);
  fx.flash = Math.max(0, fx.flash - dt);
}

/** Draws every live particle. */
export function drawEffects(ctx, fx) {
  for (const p of fx.list) {
    const k = p.age / p.life;
    const alpha = 1 - k;
    if (p.kind === 'word') {
      ctx.globalAlpha = Math.min(1, alpha * 1.6);
      const pop = 1 + Math.max(0, 0.25 - p.age) * 2;
      text(ctx, p.text, p.x, p.y, { size: p.size * pop, color: p.color, align: 'center', line: 6 });
    } else if (p.kind === 'bubble') {
      ctx.globalAlpha = alpha * 0.9;
      blob(ctx, p.x, p.y, p.size, 'rgba(214,250,255,0.25)', 'rgba(214,250,255,0.8)', 1.5);
    } else if (p.kind === 'steam' || p.kind === 'smoke') {
      ctx.globalAlpha = alpha * (p.kind === 'steam' ? 0.35 : 0.5);
      blob(ctx, p.x, p.y, p.size * (1 + k), p.kind === 'steam' ? '#ffffff' : '#3a3a42', null);
    } else if (p.kind === 'ink') {
      ctx.globalAlpha = alpha * 0.85;
      blob(ctx, p.x, p.y, p.size * (1 + k * 0.8), '#3b2a4d', null);
    } else if (p.kind === 'coin') {
      ctx.globalAlpha = 1;
      blob(ctx, p.x, p.y, p.size, PALETTE.gold, PALETTE.ink, 2);
    } else {
      ctx.globalAlpha = alpha;
      blob(ctx, p.x, p.y, p.size, p.color ?? PALETTE.gold, null);
    }
  }
  ctx.globalAlpha = 1;
}

/**
 * Every sound is synthesised with WebAudio: bubble pops, sizzle, chop clicks, the serve bell,
 * coin blips, ink puffs, the Spring Tide horn and a soft plucked-string loop.
 */

const SCALE = [0, 3, 5, 7, 10, 12, 15];
const MELODY = [0, 2, 4, 2, 5, 4, 2, 1, 0, 2, 4, 6, 5, 4, 2, 4];

/** Creates the audio system; nothing plays until the first user gesture unlocks it. */
export function createAudio() {
  return { ctx: null, master: null, music: null, muted: false, musicStep: 0, nextNote: 0, noise: null };
}

/** Starts the audio context on a user gesture. */
export function unlockAudio(audio) {
  if (audio.ctx) {
    if (audio.ctx.state === 'suspended') audio.ctx.resume();
    return;
  }
  const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
  if (!AC) return;
  audio.ctx = new AC();
  audio.master = audio.ctx.createGain();
  audio.master.gain.value = audio.muted ? 0 : 0.55;
  audio.master.connect(audio.ctx.destination);
  audio.music = audio.ctx.createGain();
  audio.music.gain.value = 0.22;
  audio.music.connect(audio.master);
  const len = audio.ctx.sampleRate;
  audio.noise = audio.ctx.createBuffer(1, len, audio.ctx.sampleRate);
  const data = audio.noise.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  audio.nextNote = audio.ctx.currentTime + 0.1;
}

/** Mutes or unmutes everything. */
export function setMuted(audio, muted) {
  audio.muted = muted;
  if (audio.master) audio.master.gain.setTargetAtTime(muted ? 0 : 0.55, audio.ctx.currentTime, 0.02);
}

/** A single oscillator note with an attack-decay envelope. */
function tone(audio, { freq, type = 'sine', dur = 0.15, vol = 0.3, slide = 0, at = 0, dest = null }) {
  const c = audio.ctx;
  const t = c.currentTime + at;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, t);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g).connect(dest ?? audio.master);
  o.start(t);
  o.stop(t + dur + 0.02);
}

/** A filtered noise burst for sizzles, chops and puffs. */
function hiss(audio, { dur = 0.2, vol = 0.2, freq = 3000, q = 0.8, type = 'bandpass', at = 0 }) {
  const c = audio.ctx;
  const t = c.currentTime + at;
  const src = c.createBufferSource();
  src.buffer = audio.noise;
  const f = c.createBiquadFilter();
  f.type = type;
  f.frequency.value = freq;
  f.Q.value = q;
  const g = c.createGain();
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(f).connect(g).connect(audio.master);
  src.start(t, Math.random() * 0.5, dur + 0.05);
}

const SOUNDS = {
  grab: (a) => tone(a, { freq: 520, slide: 380, dur: 0.09, vol: 0.18 }),
  place: (a) => tone(a, { freq: 300, slide: 500, dur: 0.12, vol: 0.2 }),
  chop: (a) => hiss(a, { dur: 0.05, vol: 0.25, freq: 2400, q: 2 }),
  chopDone: (a) => tone(a, { freq: 660, dur: 0.1, vol: 0.15, type: 'triangle' }),
  perfect: (a) => { tone(a, { freq: 880, dur: 0.12, vol: 0.16, type: 'triangle' }); tone(a, { freq: 1320, dur: 0.16, vol: 0.12, type: 'triangle', at: 0.07 }); },
  overdone: (a) => tone(a, { freq: 420, dur: 0.12, vol: 0.12, type: 'square' }),
  flipReady: (a) => tone(a, { freq: 740, dur: 0.08, vol: 0.12, type: 'square' }),
  flip: (a) => hiss(a, { dur: 0.35, vol: 0.22, freq: 4200, q: 0.6 }),
  burnt: (a) => hiss(a, { dur: 0.6, vol: 0.2, freq: 700, q: 0.5, type: 'lowpass' }),
  take: (a) => tone(a, { freq: 600, slide: 200, dur: 0.1, vol: 0.16 }),
  plateAdd: (a) => tone(a, { freq: 760, dur: 0.08, vol: 0.14, type: 'triangle' }),
  finish: (a) => { tone(a, { freq: 523, dur: 0.12, vol: 0.18, type: 'triangle' }); tone(a, { freq: 784, dur: 0.18, vol: 0.16, type: 'triangle', at: 0.08 }); },
  serve: (a) => { tone(a, { freq: 1568, dur: 0.9, vol: 0.16 }); tone(a, { freq: 2349, dur: 0.7, vol: 0.08, at: 0.01 }); tone(a, { freq: 988, dur: 0.12, vol: 0.12, type: 'square', at: 0.12 }); },
  miss: (a) => tone(a, { freq: 330, slide: -160, dur: 0.4, vol: 0.18, type: 'sawtooth' }),
  trash: (a) => hiss(a, { dur: 0.3, vol: 0.2, freq: 500, q: 0.7, type: 'lowpass' }),
  invalid: (a) => tone(a, { freq: 200, dur: 0.08, vol: 0.12, type: 'square' }),
  noArm: (a) => { tone(a, { freq: 240, dur: 0.08, vol: 0.14, type: 'square' }); tone(a, { freq: 180, dur: 0.1, vol: 0.14, type: 'square', at: 0.09 }); },
  spawn: (a) => tone(a, { freq: 990, dur: 0.07, vol: 0.08, type: 'triangle' }),
  rushWarn: (a) => tone(a, { freq: 220, slide: 220, dur: 0.6, vol: 0.14, type: 'sawtooth' }),
  rushStart: (a) => { tone(a, { freq: 196, dur: 0.7, vol: 0.18, type: 'sawtooth' }); tone(a, { freq: 294, dur: 0.7, vol: 0.12, type: 'sawtooth', at: 0.05 }); },
  orderChanged: (a) => tone(a, { freq: 700, slide: -300, dur: 0.2, vol: 0.14, type: 'triangle' }),
  twinBonus: (a) => { tone(a, { freq: 1046, dur: 0.1, vol: 0.12 }); tone(a, { freq: 1318, dur: 0.14, vol: 0.12, at: 0.08 }); },
  criticVerdict: (a) => { for (let i = 0; i < 4; i++) tone(a, { freq: 523 * 2 ** (i / 4), dur: 0.15, vol: 0.12, type: 'triangle', at: i * 0.08 }); },
  nightOver: (a) => { for (let i = 0; i < 3; i++) tone(a, { freq: 392 * 2 ** (i / 3), dur: 0.4, vol: 0.14, type: 'triangle', at: i * 0.14 }); },
  click: (a) => tone(a, { freq: 880, dur: 0.05, vol: 0.1, type: 'triangle' }),
};

/** Plays the sound for a game event, if any. */
export function playEvent(audio, type) {
  if (!audio.ctx || audio.muted) return;
  SOUNDS[type]?.(audio);
}

/** Schedules the plucked-string loop a little ahead of time; faster during a Spring Tide. */
export function updateMusic(audio, playing, rush) {
  if (!audio.ctx || audio.muted || !playing) return;
  const c = audio.ctx;
  const beat = rush ? 0.2 : 0.27;
  while (audio.nextNote < c.currentTime + 0.25) {
    const step = audio.musicStep % MELODY.length;
    const note = SCALE[MELODY[step]];
    const freq = 220 * 2 ** (note / 12);
    tone(audio, { freq, dur: 0.45, vol: 0.5, type: 'triangle', at: audio.nextNote - c.currentTime, dest: audio.music });
    if (step % 4 === 0) tone(audio, { freq: freq / 2, dur: 0.6, vol: 0.4, at: audio.nextNote - c.currentTime, dest: audio.music });
    audio.musicStep++;
    audio.nextNote += beat;
  }
}

args.newStr:
/** Octavia waving all eight arms, for the title and results screens; (x, y) is her centre. */
export function drawOctaviaPortrait(ctx, x, y, scale, t) {
  const o = LAYOUT.octavia;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.translate(-o.x, -o.y);
  drawBody(ctx, { x: o.x + 120, y: o.y + 60 }, t, Math.sin(t * 0.9) > 0.985);
  ARM_ROOTS.forEach((root, i) => {
    const side = i < 4 ? -1 : 1;
    const k = i < 4 ? 3 - i : i - 4;
    const wave = Math.sin(t * 1.6 + i * 0.9);
    const tip = { x: root.x + side * (70 + k * 44), y: root.y + 40 + k * 26 - (k === 3 ? 120 + wave * 30 : wave * 18) };
    drawTentacle(ctx, root, tip, i, t);
  });
  ctx.restore();
}

/**
 * Draws Octavia with every arm: tentacles behind the counter edge reach to their tips, holding
 * arms show their item, chopping and stirring arms carry a knife or a ladle.
 */

args.text:
/**
 * The screens around service: title, reef map, night results with the Tide Shop, and the
 * help, pause and settings overlays. Each draw call returns the buttons it laid out, so the
 * input layer can hit-test exactly what was drawn.
 */

import { PALETTE } from '../config.js';
import { CUSTOMERS } from '../data/customers.js';
import { NIGHTS } from '../data/nights.js';
import { RECIPE } from '../data/recipes.js';
import { UPGRADES, totalStars } from '../campaign.js';
import { blob, keycap, label, oval, panel, roundRect, star, starRow, TAU, text } from './draw.js';
import { drawCustomer } from './customers.js';
import { drawFinishedDish, drawIngredient } from './food.js';
import { drawOctaviaPortrait } from './octopus.js';

const INK = PALETTE.ink;

/** Deep water with light rays, a sand floor, coral and kelp. */
export function drawSea(ctx, t, calm) {
  const g = ctx.createLinearGradient(0, 0, 0, 800);
  g.addColorStop(0, '#1b7f95');
  g.addColorStop(0.55, '#0e3b43');
  g.addColorStop(1, '#082a30');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1280, 800);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 6; i++) {
    const x = 140 + i * 210 + (calm ? 0 : Math.sin(t * 0.3 + i) * 30);
    ctx.fillStyle = 'rgba(127,240,255,0.05)';
    ctx.beginPath();
    ctx.moveTo(x - 30, 0);
    ctx.lineTo(x + 40, 0);
    ctx.lineTo(x + 160, 800);
    ctx.lineTo(x + 40, 800);
    ctx.fill();
  }
  ctx.restore();
  ctx.fillStyle = '#d9b57a';
  ctx.beginPath();
  ctx.moveTo(0, 690);
  for (let x = 0; x <= 1280; x += 40) ctx.lineTo(x, 690 + Math.sin(x * 0.01) * 14);
  ctx.lineTo(1280, 800);
  ctx.lineTo(0, 800);
  ctx.fill();
  const corals = [[70, '#ff7a59'], [190, '#c9b8ff'], [1090, '#ff9aa8'], [1210, '#ffd166']];
  for (const [x, col] of corals) {
    ctx.strokeStyle = col;
    ctx.lineWidth = 10;
    ctx.lineCap = 'round';
    for (let k = -1; k <= 1; k++) {
      ctx.beginPath();
      ctx.moveTo(x, 700);
      ctx.quadraticCurveTo(x + k * 30, 640, x + k * 44, 600 - Math.abs(k) * -20);
      ctx.stroke();
    }
    ctx.lineCap = 'butt';
  }
  ctx.strokeStyle = '#2e7d4f';
  ctx.lineWidth = 8;
  for (let i = 0; i < 6; i++) {
    const x = 300 + i * 140;
    ctx.beginPath();
    ctx.moveTo(x, 720);
    for (let y = 720; y > 560; y -= 20) ctx.lineTo(x + Math.sin(y * 0.05 + t * (calm ? 0 : 1.2) + i) * 10, y);
    ctx.stroke();
  }
  for (let i = 0; i < 24; i++) {
    const x = (i * 157) % 1280;
    const y = 800 - ((t * (20 + (i % 5) * 9) + i * 97) % 820);
    blob(ctx, x + Math.sin(t + i) * 6, y, 2 + (i % 4), 'rgba(214,250,255,0.18)', 'rgba(214,250,255,0.5)', 1);
  }
}

/** A chunky button; returns its rectangle with an id. */
function button(ctx, id, str, x, y, w, h, { key = null, primary = false, disabled = false } = {}) {
  panel(ctx, x, y, w, h, { fill: disabled ? '#6b7f84' : primary ? PALETTE.coral : PALETTE.pearl, stroke: INK, r: 16, line: 3.5 });
  text(ctx, str, x + w / 2 - (key ? 18 : 0), y + h / 2 + 8, { size: 22, color: primary ? PALETTE.pearl : INK, align: 'center', outline: primary ? INK : null, line: 4 });
  if (key) keycap(ctx, key, x + w - 34, y + h / 2, { size: 13 });
  return { id, x, y, w, h, disabled };
}

/** The game's logo: two lines of chunky outlined type. */
export function drawLogo(ctx, x, y, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  text(ctx, "Octavia's", 0, 0, { size: 46, color: PALETTE.gold, align: 'center', line: 9 });
  text(ctx, 'TIDEPOOL KITCHEN', 0, 70, { size: 66, color: PALETTE.pearl, outline: PALETTE.coralDark, align: 'center', line: 12 });
  text(ctx, 'TIDEPOOL KITCHEN', 0, 70, { size: 66, color: PALETTE.pearl, outline: INK, align: 'center', line: 5 });
  ctx.restore();
}

/** Title screen. */
export function drawTitle(ctx, campaign, t, calm) {
  drawSea(ctx, t, calm);
  ctx.fillStyle = 'rgba(255,246,230,0.12)';
  ctx.beginPath();
  ctx.ellipse(380, 560, 330, 200, 0, Math.PI, 0);
  ctx.fill();
  drawOctaviaPortrait(ctx, 380, 470, 1.55, t);
  drawLogo(ctx, 900, 150);
  text(ctx, 'An eight-armed octopus chef runs a bistro inside a giant clam', 900, 262, { size: 19, color: PALETTE.foam, align: 'center', line: 4 });
  const chips = ['8 recipes', '10 ingredients', '5 stations', '5 tide nights', 'sea-creature regulars'];
  let cx = 650;
  chips.forEach((c, i) => {
    const w = c.length * 9.5 + 26;
    panel(ctx, cx, 286 + (i > 2 ? 40 : 0), w, 30, { fill: '#1d6f7a', stroke: INK, r: 15, line: 2.5, shadow: false });
    label(ctx, c, cx + w / 2, 307 + (i > 2 ? 40 : 0), 15, PALETTE.pearl, 'center', 800);
    cx += w + 10;
    if (i === 2) cx = 700;
  });
  const buttons = [
    button(ctx, 'play', 'Play', 760, 380, 280, 64, { key: 'Enter', primary: true }),
    button(ctx, 'help', 'How to play', 760, 458, 280, 56, { key: 'H' }),
    button(ctx, 'settings', 'Settings', 760, 528, 280, 56, { key: 'O' }),
  ];
  const stars = totalStars(campaign);
  text(ctx, `Campaign: ${stars}/15 stars  -  purse ${campaign.purse} coins`, 900, 624, { size: 16, color: PALETTE.pearl, align: 'center', line: 4 });
  const regulars = ['puffy', 'shelby', 'twins', 'tortuga', 'mantis'];
  regulars.forEach((id, i) => {
    const x = 120 + i * 92;
    drawCustomer(ctx, id, x, 742, 34, 0.9, t);
    ctx.lineWidth = 3;
    ctx.strokeStyle = INK;
    ctx.beginPath();
    ctx.arc(x, 742, 34, 0, TAU);
    ctx.stroke();
  });
  text(ctx, 'Tonight\u2019s regulars', 304, 694, { size: 16, color: PALETTE.gold, align: 'center', line: 4 });
  text(ctx, 'Keyboard and mouse  -  works offline  -  progress saves', 900, 760, { size: 14, color: 'rgba(255,246,230,0.8)', align: 'center', line: 3 });
  return buttons;
}

/** Positions of the five nights on the reef map. */
const MAP_NODES = [[150, 560], [330, 430], [520, 560], [700, 420], [880, 520]];

/** The reef map: the campaign path, stars per night, details and the shop door. */
export function drawMap(ctx, campaign, selected, t, calm) {
  drawSea(ctx, t, calm);
  drawLogo(ctx, 470, 72, 0.62);
  text(ctx, 'REEF MAP', 470, 168, { size: 22, color: PALETTE.foam, align: 'center', line: 5 });
  ctx.setLineDash([4, 14]);
  ctx.lineCap = 'round';
  ctx.lineWidth = 8;
  ctx.strokeStyle = 'rgba(255,246,230,0.7)';
  ctx.beginPath();
  MAP_NODES.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.lineCap = 'butt';
  const buttons = [];
  MAP_NODES.forEach(([x, y], i) => {
    const open = i < campaign.unlocked;
    const sel = i === selected;
    if (sel) {
      ctx.save();
      ctx.shadowColor = PALETTE.gold;
      ctx.shadowBlur = 24;
      blob(ctx, x, y, 58, 'rgba(255,209,102,0.35)', null);
      ctx.restore();
    }
    ctx.beginPath();
    ctx.moveTo(x - 50, y + 10);
    ctx.bezierCurveTo(x - 54, y - 58, x + 54, y - 58, x + 50, y + 10);
    ctx.quadraticCurveTo(x, y + 30, x - 50, y + 10);
    ctx.fillStyle = open ? (sel ? '#ffe3a3' : '#fff1d6') : '#6b7f84';
    ctx.fill();
    ctx.lineWidth = 3.5;
    ctx.strokeStyle = INK;
    ctx.stroke();
    text(ctx, String(i + 1), x, y - 2, { size: 34, color: open ? PALETTE.coralDark : '#3b4a4f', align: 'center', outline: null });
    text(ctx, NIGHTS[i].name, x, y + 50, { size: 17, color: PALETTE.pearl, align: 'center', line: 4 });
    for (let s = 0; s < 3; s++) star(ctx, x - 26 + s * 26, y + 74, 11, s < campaign.stars[i] ? PALETTE.gold : 'rgba(20,30,40,0.5)');
    if (!open) text(ctx, 'locked', x, y + 100, { size: 13, color: '#c7d3d6', align: 'center', line: 3 });
    buttons.push({ id: `night${i}`, x: x - 56, y: y - 56, w: 112, h: 140 });
  });
  const night = NIGHTS[selected];
  const px = 980;
  panel(ctx, px, 40, 284, 620, { fill: 'rgba(8,42,48,0.92)', stroke: '#c99a4b', r: 18, line: 4 });
  text(ctx, `NIGHT ${selected + 1}`, px + 142, 82, { size: 20, color: PALETTE.gold, align: 'center', line: 4 });
  text(ctx, night.name, px + 142, 114, { size: 28, color: PALETTE.pearl, align: 'center', line: 5 });
  label(ctx, `3:00 of service - ${night.rushes.length} Spring Tide${night.rushes.length > 1 ? 's' : ''}`, px + 142, 140, 14, PALETTE.foam, 'center', 800);
  label(ctx, 'MENU', px + 20, 172, 14, PALETTE.gold, 'left', 900);
  night.recipes.forEach((id, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = px + 20 + col * 132;
    const y = 196 + row * 54;
    drawFinishedDish(ctx, id, x + 22, y + 10, 50);
    label(ctx, RECIPE[id].name, x + 50, y + 14, 12, PALETTE.pearl, 'left', 700);
  });
  const ry = 196 + Math.ceil(night.recipes.length / 2) * 54 + 6;
  label(ctx, 'REGULARS', px + 20, ry, 14, PALETTE.gold, 'left', 900);
  const regs = Object.keys(night.customers).concat(night.critic.length ? ['mantis'] : []);
  regs.forEach((id, i) => {
    const x = px + 42 + i * 52;
    drawCustomer(ctx, id, x, ry + 32, 22, 0.9, t);
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = INK;
    ctx.beginPath();
    ctx.arc(x, ry + 32, 22, 0, TAU);
    ctx.stroke();
  });
  label(ctx, night.tip, px + 20, ry + 84, 13, PALETTE.pearl, 'left', 700);
  label(ctx, `Stars: ${night.stars.join(' / ')} coins`, px + 20, ry + 108, 13, PALETTE.foam, 'left', 800);
  const open = selected < campaign.unlocked;
  buttons.push(button(ctx, 'start', open ? 'Start night' : 'Locked', px + 22, 566, 240, 60, { key: 'Enter', primary: open, disabled: !open }));
  buttons.push(button(ctx, 'shop', 'Tide Shop', 40, 690, 240, 56, { key: 'U' }));
  buttons.push(button(ctx, 'title', 'Title', 300, 690, 170, 56, { key: 'Esc' }));
  panel(ctx, 500, 690, 450, 56, { fill: 'rgba(8,42,48,0.9)', stroke: INK, r: 16, line: 3 });
  text(ctx, `Purse ${campaign.purse} coins  -  ${totalStars(campaign)}/15 stars`, 725, 726, { size: 18, color: PALETTE.gold, align: 'center', line: 4 });
  const owned = UPGRADES.filter((u) => campaign.upgrades[u.id]);
  owned.forEach((u, i) => drawUpgradeIcon(ctx, u.id, 1000 + i * 50, 718, 20));
  return buttons;
}

/** Small icons for the Tide Shop upgrades. */
export function drawUpgradeIcon(ctx, id, x, y, r) {
  blob(ctx, x, y, r, '#1d6f7a', INK, 2.5);
  if (id === 'secondPot') {
    ctx.fillStyle = '#4fb7b0';
    roundRect(ctx, x - r * 0.55, y - r * 0.2, r * 1.1, r * 0.7, r * 0.2);
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = INK;
    ctx.stroke();
    oval(ctx, x, y - r * 0.2, r * 0.55, r * 0.16, '#fbf3e4', INK, 1.5);
  } else if (id === 'quickArms') {
    ctx.strokeStyle = '#ff8a7a';
    ctx.lineWidth = r * 0.3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x - r * 0.5, y + r * 0.4);
    ctx.quadraticCurveTo(x - r * 0.1, y - r * 0.6, x + r * 0.5, y - r * 0.2);
    ctx.stroke();
    ctx.lineCap = 'butt';
    ctx.strokeStyle = PALETTE.pearl;
    ctx.lineWidth = 2;
    for (const k of [-1, 0, 1]) {
      ctx.beginPath();
      ctx.moveTo(x - r * 0.9, y + k * r * 0.25);
      ctx.lineTo(x - r * 0.55, y + k * r * 0.25);
      ctx.stroke();
    }
  } else if (id === 'calmingCoral') {
    ctx.strokeStyle = '#ff9aa8';
    ctx.lineWidth = r * 0.22;
    ctx.lineCap = 'round';
    for (const k of [-1, 0, 1]) {
      ctx.beginPath();
      ctx.moveTo(x, y + r * 0.6);
      ctx.lineTo(x + k * r * 0.45, y - r * 0.45);
      ctx.stroke();
    }
    ctx.lineCap = 'butt';
  } else if (id === 'autoStir') {
    ctx.strokeStyle = '#c9b8ff';
    ctx.lineWidth = r * 0.16;
    ctx.lineCap = 'round';
    for (let k = 0; k < 6; k++) {
      ctx.beginPath();
      ctx.moveTo(x + (k - 2.5) * r * 0.16, y + r * 0.45);
      ctx.quadraticCurveTo(x + (k - 2.5) * r * 0.3, y - r * 0.1, x + (k - 2.5) * r * 0.22, y - r * 0.55);
      ctx.stroke();
    }
    ctx.lineCap = 'butt';
  } else {
    ctx.beginPath();
    ctx.moveTo(x - r * 0.7, y);
    ctx.bezierCurveTo(x - r * 0.7, y - r * 0.9, x + r * 0.7, y - r * 0.9, x + r * 0.7, y);
    ctx.closePath();
    ctx.fillStyle = '#efe4ff';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = INK;
    ctx.stroke();
    oval(ctx, x, y + r * 0.15, r * 0.72, r * 0.3, '#9ad9c6', INK, 2);
  }
}

/** The Tide Shop panel: every upgrade with its cost; returns the buy buttons. */
export function drawShop(ctx, campaign, x, y, w) {
  panel(ctx, x, y, w, 470, { fill: 'rgba(8,42,48,0.94)', stroke: '#c99a4b', r: 18, line: 4 });
  text(ctx, 'TIDE SHOP', x + w / 2, y + 40, { size: 26, color: PALETTE.gold, align: 'center', line: 5 });
  text(ctx, `purse ${campaign.purse} coins`, x + w / 2, y + 66, { size: 16, color: PALETTE.pearl, align: 'center', line: 3 });
  const buttons = [];
  UPGRADES.forEach((u, i) => {
    const ry = y + 84 + i * 76;
    const owned = !!campaign.upgrades[u.id];
    const afford = campaign.purse >= u.cost;
    panel(ctx, x + 14, ry, w - 28, 68, { fill: owned ? '#1d6f5a' : '#12474f', stroke: INK, r: 12, line: 2.5, shadow: false });
    drawUpgradeIcon(ctx, u.id, x + 48, ry + 34, 22);
    text(ctx, u.name, x + 80, ry + 28, { size: 17, color: PALETTE.pearl, line: 3 });
    label(ctx, u.text, x + 80, ry + 50, 12, PALETTE.foam, 'left', 700);
    const bx = x + w - 120;
    if (owned) {
      text(ctx, 'OWNED', bx + 50, ry + 41, { size: 16, color: PALETTE.green, align: 'center', line: 3 });
    } else {
      panel(ctx, bx, ry + 16, 96, 36, { fill: afford ? PALETTE.gold : '#6b7f84', stroke: INK, r: 10, line: 2.5, shadow: false });
      label(ctx, `${u.cost} c`, bx + 48, ry + 40, 16, INK, 'center', 900);
      buttons.push({ id: `buy:${u.id}`, x: bx, y: ry + 16, w: 96, h: 36, disabled: !afford });
    }
  });
  return buttons;
}

/** Results of a night: stars, coins, stats, the critic and the Tide Shop. */
export function drawResults(ctx, campaign, summary, t, calm) {
  drawSea(ctx, t, calm);
  const night = NIGHTS[summary.nightIndex];
  panel(ctx, 30, 30, 700, 740, { fill: 'rgba(8,42,48,0.94)', stroke: '#c99a4b', r: 22, line: 5 });
  text(ctx, `NIGHT ${summary.nightIndex + 1} COMPLETE`, 380, 84, { size: 34, color: PALETTE.gold, align: 'center', line: 7 });
  text(ctx, night.name, 380, 118, { size: 22, color: PALETTE.foam, align: 'center', line: 4 });
  for (let s = 0; s < 3; s++) {
    const appear = Math.min(1, Math.max(0, t * 2 - s * 0.4));
    const sc = calm ? 1 : 0.6 + 0.4 * appear;
    star(ctx, 270 + s * 110, 196 - (s === 1 ? 14 : 0), 44 * sc, s < summary.stars ? PALETTE.gold : 'rgba(20,30,40,0.55)', INK, 4);
  }
  text(ctx, `${summary.coins} coins`, 380, 290, { size: 40, color: PALETTE.pearl, align: 'center', line: 7 });
  label(ctx, `targets ${night.stars.join(' / ')}`, 380, 316, 15, PALETTE.foam, 'center', 800);
  const stats = [
    ['Plates served', summary.served], ['Customers missed', summary.missed],
    ['Perfect cooks', summary.perfectCooks], ['Best Ink Streak', summary.bestStreak],
    ['Tips earned', `${summary.tips} c`], ['Burnt food', summary.burnt],
    ['Twin bonuses', summary.twins], ['Orders changed', summary.ordersChanged],
  ];
  stats.forEach(([name, value], i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = 70 + col * 320;
    const y = 360 + row * 60;
    panel(ctx, x, y, 300, 48, { fill: '#12474f', stroke: INK, r: 12, line: 2.5, shadow: false });
    label(ctx, name, x + 16, y + 30, 17, PALETTE.foam, 'left', 800);
    text(ctx, String(value), x + 284, y + 33, { size: 22, color: PALETTE.pearl, align: 'right', line: 4 });
  });
  if (summary.critic !== null) {
    panel(ctx, 70, 604, 620, 56, { fill: '#3b2a4d', stroke: PALETTE.gold, r: 14, line: 3, shadow: false });
    drawCustomer(ctx, 'mantis', 108, 632, 22, 0.9, t);
    text(ctx, 'Madame Mantis reviews:', 142, 640, { size: 18, color: PALETTE.gold, line: 4 });
    starRow(ctx, 560, 632, 12, summary.critic);
  } else {
    drawOctaviaPortrait(ctx, 380, 640, 0.42, t);
  }
  const buttons = [];
  const nextOpen = summary.nightIndex + 1 < Math.min(NIGHTS.length, campaign.unlocked);
  if (summary.nightIndex + 1 < NIGHTS.length) buttons.push(button(ctx, 'next', 'Next night', 60, 690, 230, 60, { key: 'Enter', primary: nextOpen, disabled: !nextOpen }));
  buttons.push(button(ctx, 'retry', 'Replay', 302, 690, 190, 60, { key: 'R' }));
  buttons.push(button(ctx, 'map', 'Reef map', 504, 690, 200, 60, { key: 'M' }));
  return buttons.concat(drawShop(ctx, campaign, 760, 160, 490), [drawShopHeader(ctx, t)]).filter(Boolean);
}

/** Octavia's note above the shop. */
function drawShopHeader(ctx, t) {
  panel(ctx, 760, 40, 490, 100, { fill: PALETTE.pearl, stroke: INK, r: 18, line: 3 });
  drawIngredient(ctx, 'pearl', 812, 90, 60, null, t);
  text(ctx, 'Spend your coins on the kitchen', 1020, 82, { size: 20, color: INK, align: 'center', outline: null });
  label(ctx, 'Upgrades last for the whole campaign', 1020, 110, 15, '#5a4470', 'center', 800);
  return null;
}

/** A dark veil over the kitchen for overlays. */
function veil(ctx) {
  ctx.fillStyle = 'rgba(5,25,29,0.72)';
  ctx.fillRect(0, 0, 1280, 800);
}

/** How to play. */
export function drawHelp(ctx, t) {
  veil(ctx);
  panel(ctx, 90, 50, 1100, 700, { fill: PALETTE.pearl, stroke: INK, r: 24, line: 4 });
  text(ctx, 'HOW TO RUN THE TIDEPOOL KITCHEN', 640, 100, { size: 30, color: PALETTE.coralDark, align: 'center', outline: null });
  const rows = [
    ['1-0', 'Grab an ingredient from its bin. Each item takes one of Octavia\u2019s 8 arms.'],
    ['Q', 'Shell Board: chop. Chopping only moves while an arm works the board.'],
    ['W', 'Bubble Pot: simmer. The placing arm stirs; an unstirred pot burns twice as fast.'],
    ['E', 'Vent Grill: sear. When it shouts FLIP!, press E again before it chars.'],
    ['R', 'Kelp Steamer: steam. Two baskets, gentle and slow.'],
    ['Space', 'Clam Plate: lay held food on the dish, then press again to finish (Roll, Ladle...).'],
    ['S', 'Serve the glowing plate in the Current Window to the customer who ordered it.'],
