  return [{ id: 'closeHelp', x: 0, y: 0, w: 1280, h: 800 }];
}

/** Pause menu. */
export function drawPause(ctx) {
  veil(ctx);
  panel(ctx, 440, 190, 400, 420, { fill: 'rgba(8,42,48,0.96)', stroke: '#c99a4b', r: 24, line: 4 });
