/**
 * Creates a chef that acts at most once per `cadence` seconds, plans `focus` tickets ahead and
 * lets a finished plate sit on the pass for `serveAfter` seconds before serving it.
 */
export function createAutoChef({ cadence = 0.24, focus = 3, serveAfter = 0 } = {}) {
