args.text:
/**
 * Deterministic screenshot scenes, opened with ?scene=<name>&seed=<n>. Each one reaches its
 * moment by playing the real game with the scripted chef (campaign nights included), then
 * freezes the frame. The last seconds run through the normal app update so the effects,
 * arm motion and popups on screen are the ones play produced.
 */

import { STEP } from './config.js';
import { CUSTOMERS } from './data/customers.js';
import { createNight, nightSummary } from './state.js';
import { createAutoChef, chefThink, simulateNight } from './autochef.js';
import { buyUpgrade, newCampaign, recordNight } from './campaign.js';
import { cookProgress } from './stations.js';
import { missingParts } from './orders.js';
import { drainEvents, updateApp } from './app.js';
import { createArmView } from './render/octopus.js';
import { createEffects } from './render/effects.js';

/** Plays campaign nights with the chef, banks them and buys upgrades along the way. */
function playCampaign(nights, seed, buys) {
  const campaign = newCampaign();
  campaign.seenHelp = true;
  for (let i = 0; i < nights; i++) {
    const night = createNight({ nightIndex: i, upgrades: campaign.upgrades, seed: seed + i });
    simulateNight(night, createAutoChef({ cadence: [0.45, 0.8, 0.55, 0.5, 0.5][i], focus: 2 }));
    recordNight(campaign, nightSummary(night));
    for (const id of buys[i] ?? []) buyUpgrade(campaign, id);
  }
  return campaign;
}

/**
 * Plays a night with the chef and stops at the first frame after `from` where `moment` holds;
 * the final stretch runs through the app so effects and arms are live.
 */
function playToMoment(app, nightIndex, seed, from, moment, chefOpts) {
  const night = createNight({ nightIndex, upgrades: app.campaign.upgrades, seed });
  const chef = createAutoChef(chefOpts);
  app.night = night;
  app.screen = 'night';
  app.overlay = null;
  app.armView = createArmView();
  app.fx = createEffects();
  simulateNight(night, chef, from - 2);
  const memory = { lastServe: null };
  while (!night.over) {
    chefThink(night, chef, STEP);
    for (const e of night.events) if (e.type === 'serve') memory.lastServe = { at: night.time, ...e };
    drainEvents(app);
    updateApp(app, STEP);
    if (night.time >= from && moment(night, memory)) return true;
  }
  return false;
}

/** Whether any pot is a breath away from its perfect window. */
function potNearlyPerfect(night) {
  return ['pot0', 'pot1'].some((id) => {
    const item = night.stations[id].slots[0];
    return item && item.phase === 'cook' && cookProgress(item) > 0.8 && cookProgress(item) < 0.97;
  });
}

/** Whether the plate holds a dish with at least two parts on and one still to come. */
function plateMidAssembly(night) {
  const plate = night.plate;
  return !!plate.recipeId && plate.parts.length >= 2 && missingParts(plate.recipeId, plate.parts).length >= 1;
}

const SCENES = {
  /** Mid-rush service with every element the cover needs. */
  cover(app, seed) {
    app.campaign = playCampaign(3, seed, { 1: ['secondPot'], 2: ['biggerPlate'] });
    playToMoment(app, 3, seed, 52, (n) => n.rush.active && n.streak >= 6 && plateMidAssembly(n) && n.pass.length >= 1
      && potNearlyPerfect(n) && n.tickets.length >= 4 && n.toasts.length === 0, { serveAfter: 2.2, cadence: 0.3 });
  },
  /** The title header over the reef map, a few nights into the campaign. */
  map(app, seed) {
    app.campaign = playCampaign(3, seed, { 1: ['secondPot'], 2: ['biggerPlate'] });
    app.screen = 'map';
    app.mapSel = 3;
    app.t = 4;
  },
  /** King Tide: Madame Mantis waits during a Spring Tide while combo popups fly. */
  critic(app, seed) {
    app.campaign = playCampaign(4, seed, { 1: ['secondPot'], 2: ['biggerPlate'], 3: ['quickArms'] });
    playToMoment(app, 4, seed, 96, (n, m) => n.rush.active && n.tickets.some((t) => CUSTOMERS[t.customerId].vip)
      && m.lastServe && n.time - m.lastServe.at > 0.25 && n.time - m.lastServe.at < 0.6 && m.lastServe.mult >= 2, { serveAfter: 1.2, cadence: 0.3 });
  },
  /** Results of Storm Tide with stars, stats and the Tide Shop. */
  results(app, seed) {
    app.campaign = playCampaign(4, seed, { 1: ['secondPot'], 2: ['biggerPlate'] });
    const night = createNight({ nightIndex: 3, upgrades: app.campaign.upgrades, seed: seed + 3 });
    simulateNight(night, createAutoChef({ cadence: 0.5, focus: 2 }));
    app.summary = nightSummary(night);
    app.screen = 'results';
    app.t = 3;
  },
};

/** Builds a named scene and freezes it; returns false for an unknown name. */
export function applyScene(app, name, seed) {
  const scene = SCENES[name];
  if (!scene) return false;
  scene(app, seed);
  app.frozen = true;
  return true;
}

/**
 * Boot: fits the 1280x800 canvas to the window, loads the campaign, wires input and runs a
 * fixed-step loop. A ?scene= query opens a deterministic screenshot scene instead.
 */

import { STEP, VIEW_H, VIEW_W } from './config.js';
import { loadCampaign } from './campaign.js';
import { createAudio } from './audio.js';
import { createApp, drawApp, handleKey, handlePointer, updateApp } from './app.js';
import { bindInput } from './input.js';
import { applyScene } from './shots.js';

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

/** Sizes the canvas backing store for the window and device pixel ratio, keeping 16:10. */
function fit() {
  const scale = Math.min(window.innerWidth / VIEW_W, window.innerHeight / VIEW_H);
  const dpr = window.devicePixelRatio || 1;
  canvas.style.width = `${Math.floor(VIEW_W * scale)}px`;
  canvas.style.height = `${Math.floor(VIEW_H * scale)}px`;
  canvas.width = Math.round(VIEW_W * scale * dpr);
  canvas.height = Math.round(VIEW_H * scale * dpr);
  ctx.setTransform(canvas.width / VIEW_W, 0, 0, canvas.height / VIEW_H, 0, 0);
}

const params = new URLSearchParams(location.search);
const app = createApp({ campaign: loadCampaign(), audio: createAudio() });
const scene = params.get('scene');
if (scene) applyScene(app, scene, Number(params.get('seed') ?? 7));

bindInput(canvas, {
  onKey: (key) => (app.frozen ? false : handleKey(app, key)),
  onPointer: (kind, x, y) => { if (!app.frozen) handlePointer(app, kind, x, y); },
});
window.addEventListener('resize', fit);
fit();

let last = performance.now();
let acc = 0;
function frame(now) {
  acc = Math.min(acc + (now - last) / 1000, 0.25);
  last = now;
  while (acc >= STEP) {
    updateApp(app, STEP);
    acc -= STEP;
  }
  ctx.save();
  ctx.setTransform(canvas.width / VIEW_W, 0, 0, canvas.height / VIEW_H, 0, 0);
  drawApp(ctx, app);
  ctx.restore();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
document.body.dataset.ready = scene ? 'scene' : 'game';

// Octavia's Tidepool Kitchen: the entry program for make.fun's cooking game bounty.
// Node 22, standard library only, no build. It hands in the game exactly as it sits in this
// repository: game/ (static files a desktop browser plays offline) and screenshots/ (the
// cover first by name) are copied to the output directory, and dossier.json is written there
// with the make.fun library, byte for byte what the scorer rebuilds.
//
// The grader runs it with /output writable; anywhere else set MAKEFUN_OUTPUT_DIR:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { cpSync, existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

const root = fileURLToPath(new URL('.', import.meta.url));
const output = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
const gameDir = join(root, 'game');
const shotsDir = join(root, 'screenshots');

/** The scorer's caps from the bounty's gate: only text_max_bytes shapes the bytes, the rest refuse. */
const CAPS = {
  text_max_bytes: 163840,
  screenshots: { max: 4, max_bytes: 262144 },
  game_max_files: 993,
  game_max_bytes: 50331648,
  game_path_max_bytes: 1000,
};

/** Refuses early, with a readable reason, an entry the scorer would refuse. */
function checkEntry(): string[] {
  if (!existsSync(join(gameDir, 'index.html'))) throw new Error('game/index.html is missing');
  const shots = existsSync(shotsDir) ? readdirSync(shotsDir).filter((f) => /\.(png|jpe?g)$/i.test(f) && !f.startsWith('.')).sort() : [];
  if (shots.length < 3 || shots.length > CAPS.screenshots.max) {
    throw new Error(`screenshots/ must hold 3 or 4 images, it holds ${shots.length}`);
  }
  for (const name of shots) {
    const bytes = statSync(join(shotsDir, name)).size;
    if (bytes > CAPS.screenshots.max_bytes) throw new Error(`screenshots/${name} is ${bytes} bytes, over the 256 KiB cap`);
  }
  return shots;
}

checkEntry();
mkdirSync(output, { recursive: true });
cpSync(gameDir, join(output, 'game'), { recursive: true });
cpSync(shotsDir, join(output, 'screenshots'), { recursive: true });
writeFileSync(join(output, 'dossier.json'), buildDossier(output, CAPS));

// Local play server for Octavia's Tidepool Kitchen (Node 22, standard library only).
// `node serve.ts` serves game/ at http://localhost:8080 (`--port 9000` picks another port).
// It answers GET and HEAD for files inside game/ only, with the content types the game uses.

import { createReadStream, statSync } from 'node:fs';
import { createServer } from 'node:http';
import { extname, join, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const gameRoot = resolve(fileURLToPath(new URL('./game', import.meta.url)));
const portFlag = process.argv.indexOf('--port');
const port = portFlag > 0 ? Number(process.argv[portFlag + 1]) : 8080;

const TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
};

/** The file under game/ a request path names, or null when it would leave game/. */
function fileFor(urlPath: string): string | null {
  let path: string;
  try {
    path = decodeURIComponent(new URL(urlPath, 'http://local').pathname);
  } catch {
    return null;
  }
  if (path.endsWith('/')) path += 'index.html';
  const file = resolve(join(gameRoot, path));
  return file === gameRoot || file.startsWith(gameRoot + sep) ? file : null;
}

createServer((req, res) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405).end();
    return;
  }
  const file = fileFor(req.url ?? '/');
  if (!file) {
    res.writeHead(403).end('outside game/');
    return;
  }
  let size: number;
  try {
    const info = statSync(file);
    if (!info.isFile()) throw new Error('not a file');
    size = info.size;
  } catch {
    res.writeHead(404).end('not found');
    return;
  }
  res.writeHead(200, { 'content-type': TYPES[extname(file).toLowerCase()] ?? 'application/octet-stream', 'content-length': size, 'cache-control': 'no-store' });
  if (req.method === 'HEAD') res.end();
  else createReadStream(file).pipe(res);
}).listen(port, '127.0.0.1', () => console.log(`Octavia's Tidepool Kitchen: http://localhost:${port}`));

