import { CUSTOMERS } from '../octavias-tidepool-kitchen/game/src/data/customers.js';
const mode = process.argv[2];
function richness(s) {
  const busy = s.arms.filter(a => a.state !== 'idle').length;
  const hold = s.arms.filter(a => a.state === 'hold').length;
  let items = 0, perfect = 0;
  for (const st of Object.values(s.stations)) for (const it of st.slots) if (it && it.phase !== 'burnt') { items++; if (it.phase === 'perfect' || it.phase === 'flip') perfect++; }
  const grill = s.stations.grill.slots.some(Boolean) ? 3 : 0;
  const steam = s.stations.steamer.slots.some(Boolean) ? 2 : 0;
  return busy * 2 + hold + items * 2 + perfect * 3 + grill + steam + s.tickets.length;
}
const best = [];
const nights = mode === 'cover' ? [2, 3] : [4];
const ups = mode === 'cover' ? { secondPot: true, calmingCoral: true } : { secondPot: true, calmingCoral: true, quickArms: true };
for (const nightIndex of nights) for (const cadence of [0.45, 0.55, 0.65]) for (const serveAfter of [2, 3.5]) for (const seed of [3, 7, 11, 19]) {
  const opts = { serveAfter, cadence };
  const s = createNight({ nightIndex, upgrades: ups, seed });
  const chef = createAutoChef(opts);
  let frame = 0, lastServe = null, top = null;
  while (!s.over) {
    chefThink(s, chef, 1/60);
    for (const e of s.events) if (e.type === 'serve') lastServe = { at: s.time, mult: e.mult };
    stepNight(s, 1/60); s.events.length = 0; frame++;
    if (!s.rush.active || s.rush.endsAt - s.time < 4 || s.toasts.length || s.streak < 6) continue;
    if (!(s.plate.recipeId && s.plate.parts.length >= 2 && missingParts(s.plate.recipeId, s.plate.parts).length >= 1)) continue;
    if (mode === 'cover') {
      const p = s.pass[0];
      if (!p || !ticketForPlate(s, p) || p.warmth / p.maxWarmth < 0.5 || s.tickets.length < 5) continue;
      const pot = ['pot0','pot1'].some(id => { const it = s.stations[id].slots[0]; return it && it.phase === 'cook' && cookProgress(it) > 0.7 && cookProgress(it) < 0.97; });
      if (!pot) continue;
    } else {
      if (!s.tickets.some(t => CUSTOMERS[t.customerId].vip)) continue;
      if (!lastServe || s.time - lastServe.at < 0.25 || s.time - lastServe.at > 0.55 || lastServe.mult < 2) continue;
    }
    const r = richness(s);
    if (!top || r > top.r) top = { r, frame, t: +s.time.toFixed(3), recipe: s.plate.recipeId, tickets: s.tickets.length };
  }
  if (top) best.push({ nightIndex, seed, ...opts, ...top });
}
best.sort((a, b) => b.r - a.r);
console.log(best.slice(0, 6).map(b => JSON.stringify(b)).join('\n') || 'none');
