async (page) => {
  const root = '/projects/sandbox/octavias-tidepool-kitchen/game';
  const shots = [
    ['1-cover.jpg', '?scene=cover&seed=7'],
    ['2-map.jpg', '?scene=map&seed=7'],
    ['3-critic.jpg', '?scene=critic&seed=11'],
    ['4-results.jpg', '?scene=results&seed=7'],
  ];
  const report = [];
  await page.setViewportSize({ width: 1280, height: 800 });
  for (const [name, query] of shots) {
    await page.goto('about:blank');
    const errors = [];
    const external = [];
    page.removeAllListeners('console');
    page.removeAllListeners('pageerror');
    page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
    page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
    await page.unrouteAll({ behavior: 'ignoreErrors' });
    await page.route('**/*', async (route) => {
      const href = route.request().url();
      const m = /^https?:\/\/([^/]+)(\/[^?#]*)?/.exec(href);
      if (!m || m[1] !== 'tidepool.local') { external.push(href); return route.abort(); }
      const path = !m[2] || m[2] === '/' ? '/index.html' : m[2];
      const type = path.endsWith('.js') ? 'text/javascript' : path.endsWith('.html') ? 'text/html' : 'application/octet-stream';
      try { await route.fulfill({ path: root + path, contentType: type }); } catch (e) { errors.push('missing ' + path); await route.fulfill({ status: 404, body: 'nf' }); }
    });
    const t0 = Date.now();
    await page.goto('http://tidepool.local/index.html' + query);
    await page.waitForSelector('body[data-ready="scene"]', { timeout: 90000 });
    await page.waitForTimeout(300);
    const screen = await page.evaluate(() => document.body.dataset.screen);
    await page.screenshot({ path: '/projects/sandbox/_dev/shots/' + name, type: 'jpeg', quality: 86 });
    report.push({ name, ms: Date.now() - t0, screen, errors, external });
  }
  return JSON.stringify(report);
}

