```js
await (async (page) => {
  const root = '/projects/sandbox/octavias-tidepool-kitchen/game';
  await page.goto('about:blank');
  const errors = [];
  const external = [];
  page.removeAllListeners('console');
  page.removeAllListeners('pageerror');
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.unrouteAll({ behavior: 'ignoreErrors' });
  await page.route('**/*', async (route) => {
    const href = route.request().url();
    const m = /^https?:\/\/([^/]+)(\/[^?#]*)?/.exec(href);
    if (!m || m[1] !== 'tidepool.local') { external.push(href); return route.abort(); }
    const path = !m[2] || m[2] === '/' ? '/index.html' : m[2];
    const type = path.endsWith('.js') ? 'text/javascript' : path.endsWith('.html') ? 'text/html' : 'application/octet-stream';
    try { await route.fulfill({ path: root + path, contentType: type }); } catch (e) { errors.push('missing ' + path); await route.fulfill({ status: 404, body: 'nf' }); }
  });
  await page.goto('http://tidepool.local/index.html?autoplay&speed=12');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForSelector('body[data-screen="title"]');
  await page.keyboard.press('Enter');
  await page.waitForSelector('body[data-screen="map"]');
  await page.keyboard.press('Enter');
  await page.waitForSelector('body[data-screen="night"]');
  await page.waitForTimeout(400);
  await page.keyboard.press('h');
  const t0 = Date.now();
  await page.waitForTimeout(5000);
  await page.screenshot({ path: '/projects/sandbox/_dev/qa-mid.jpg', type: 'jpeg', quality: 70 });
  await page.waitForSelector('body[data-screen="results"]', { timeout: 90000 });
  const secs = (Date.now() - t0) / 1000;
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/projects/sandbox/_dev/qa-results.jpg', type: 'jpeg', quality: 70 });
  const save = await page.evaluate(() => localStorage.getItem('octavias-tidepool-kitchen/v1'));
  return JSON.stringify({ secs, errors, external, save });
})(page);
```
